INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (17, 'Adveretencia - dissidia e insubordinação', 'advertencia', 'Por meio deste documento, notificamos formalmente que, no dia 08/12/2024, foi identificado o descumprimento de orientação direta do gestor responsável. Especificamente, foi apurado que o conjunto de placas Cavalo FDR6I83 / Carreta FDL8F96, sob sua responsabilidade, deslocou-se para São Paulo sem a devida autorização. Tal conduta gerou custos desnecessários para a empresa.  Reforçamos que é imprescindível que todas as orientações sejam rigorosamente seguidas, a fim de garantir a eficiência operacional, o controle de custos e o alinhamento aos objetivos organizacionais. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os prejuízos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “E e H” do Art. 482 da CLT, desídia e', 'Por meio deste documento, notificamos formalmente que, no dia 08/12/2024, foi identificado o descump', 'Adveretencia - dissidia e insubordinação.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (18, 'Adveretencia - ignição ligada', 'advertencia', 'Considerando que Vossa Pessoa, na condição de motorista profissional, foi negligente no desempenho das suas funções nos 05, 10, 12 e 15   /05/2025, por deixar o veículo placa FEC2E53, com o motor ligado estando parado superior a 10 minutos, gerando consumo de óleo diesel, e custo desnecessários para a empresa, o que é contrário ás regras do empregador, atitude esta inaceitável e inadmissível por esta empresa. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os prejuízos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “E e H” do Art. 482 da CLT, desídia e indisciplina, no desempenho das respectivas funções.', 'Considerando que Vossa Pessoa, na condição de motorista profissional, foi negligente no desempenho d', 'Adveretencia - ignição ligada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (19, 'Adveretencia cinto de segurança', 'advertencia', 'Na data de 16/06/2025 foi constatado que, durante o exercício de suas funções como motorista profissional, o senhor conduziu o veículo de propriedade da empresa placa (FXM6C11), sem o uso do cinto de segurança, o que levou o bloqueio de vossa senhoria no embarcador e necessidade da reintegração, o que impede a realização de puxes para este embarcador.  Considerando também, que o não uso do cinto é um ato de descumprimento às normas internas da empresa e à legislação de trânsito vigente, conforme o artigo 65 do CTB, que estabelece o uso obrigatório do cinto de segurança por todos os ocupantes do veículo. Ressaltamos que essa conduta coloca em risco sua segurança, a segurança de terceiros, e a integridade do patrimônio da empresa. Além disso, a não utilização do cinto de segurança é uma infração grave, sujeita a penalidades previstas em lei, incluindo multas e pontos na CNH. Considerando as transgressões cometida, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disc', 'Na data de 16/06/2025 foi constatado que, durante o exercício de suas funções como motorista profiss', 'Adveretencia cinto de segurança.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (20, 'Adveretencia por falta injustificada', 'advertencia', 'Conforme registro em nosso sistema de controle de presença, constatamos sua ausência ao trabalho no dia 00/12/2024, sem devida comunicação ou justificativa formal. De acordo com as normas estabelecidas no Regulamento Interno da Empresa/CLT, a ausência injustificada ao trabalho compromete a organização e o desempenho das atividades do setor, além de configurar descumprimento das obrigações contratuais Tal conduta representa grave violação das normas internas da empresa e dos compromissos assumidos com nossos clientes, comprometendo a eficiência das operações e a confiabilidade dos nossos serviços. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando as faltas injustiçadas, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “e” do Art. 482 da CLT (d', 'Conforme registro em nosso sistema de controle de presença, constatamos sua ausência ao trabalho no ', 'Adveretencia por falta injustificada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (21, 'Adveretencia por fazer necessidades em local proíbido', 'advertencia', 'Por meio desta, comunicamos que foi constatado que vossa senhoria cometeu a infração de urinar em local proibido no pátio do embarcador BRF. Essa atitude não está de acordo com as normas de conduta, sendo considerada uma falta de respeito com o ambiente de trabalho e com os demais colegas e demais pessoas que trafegam pelo local. Lembramos que tal conduta vai contra o Regulamento Interno da Empresa, o qual estabelece que todos os colaboradores devem utilizar os banheiros designados para necessidades fisiológicas, preservando o ambiente de trabalho e zelando pela higiene e bem-estar de todos. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “E e H” do Art. ', 'Por meio desta, comunicamos que foi constatado que vossa senhoria cometeu a infração de urinar em lo', 'Adveretencia por fazer necessidades em local proíbido.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (22, 'Adveretencia por fumar enquanto dirige', 'advertencia', 'Informamos que, no dia 04 de novembro de 2024, foi verificado, por meio de registro em câmera, que durante a condução do veículo de placa KZO8G10 você estava fumando enquanto dirigia. Essa atitude infringe diretamente as normas de segurança estabelecidas pela nossa empresa e pelo cliente. A prática de fumar enquanto dirige compromete a atenção e a segurança na condução, colocando em risco tanto a sua integridade quanto a de terceiros. Além disso, tal comportamento está em desacordo com as políticas de segurança da empresa. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de suspensão por 05 (cinco) dias, sem remuneração e DSR, pela prática do disposto na alínea “e” do Art. 482 da CLT (dissidia)', 'Informamos que, no dia 04 de novembro de 2024, foi verificado, por meio de registro em câmera, que d', 'Adveretencia por fumar enquanto dirige.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (23, 'Adveretencia por marcar jornada em nome de outra pessoa', 'advertencia', 'Hugo  Considerando que Vossa Pessoa, na condição de motorista profissional, foi negligente no desempenho das suas funções nos dias 03,04,05,06,07 e 08 de agosto de 2024, por fazer marcação de jornada em seu veículo, (placa FSL9D37) para outro colaborador (Genilson Ubaldo Dos Santos) o qual estava de folga, o que é contrário às regras da empregadora, atitude esta inaceitável e inadmissível por esta empresa.   Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os prejuízos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “E e H” do Art. 482 da CLT, desídia e indisciplina, no desempenho das respectivas funções. Genilson  Considerando que Vossa Pessoa, na condição de motorista profissional, foi negligente no desempenho ', 'Hugo  Considerando que Vossa Pessoa, na condição de motorista profissional, foi negligente no desemp', 'Adveretencia por marcar jornada em nome de outra pessoa.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (24, 'Adveretncia por marcar ponto e sair do local da trabalho', 'advertencia', 'Constatou-se que, na data acima, Vossa Senhoria iniciou sua jornada de trabalho e, em seguida, ausentou-se para sua residência, mantendo a jornada aberta no sistema, sem autorização prévia do gestor imediato e sem apresentar justificativa plausível. Tal conduta caracteriza descumprimento de deveres contratuais e das normas internas da empresa Transportes Framento, configurando ato de desídia e desobediência, nos termos do artigo 482, alínea “e” e “h”, “dissida e ato de indisciplina” da Consolidação das Leis do Trabalho (CLT), além de violar o artigo 158 da CLT, que impõe ao empregado a obrigação de observar as ordens e instruções do empregador relativas ao serviço. Diante do exposto, a empresa aplica a presente ADVERTÊNCIA ESCRITA, advertindo que a reincidência poderá ensejar medidas disciplinares mais severas, inclusive a rescisão do contrato de trabalho por justa causa, conforme a legislação vigente. Salienta-se, ainda, que a presente medida está sendo adotada em observância ao princ', 'Constatou-se que, na data acima, Vossa Senhoria iniciou sua jornada de trabalho e, em seguida, ausen', 'Adveretncia por marcar ponto e sair do local da trabalho.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (25, 'Advertencia  abandono de veículo', 'advertencia', 'Por meio desta, fica registrado que, no dia 08/02/2025, Vossa Senhoria abandonou o posto de trabalho durante o expediente, sem apresentar justificativa ou comunicar previamente o gestor responsável. Tal conduta causou impactos diretos às operações da empresa, especialmente considerando que o caminhão placa FZC4034, sob sua responsabilidade, já possuía programação de carregamento, resultando em transtornos operacionais. Dessa forma, sua atitude configura descumprimento das normas internas da empresa, podendo ensejar sanções mais severas em caso de reincidência. Solicitamos que tome ciência desta advertência e observe as diretrizes da empresa, evitando futuras ocorrências semelhantes. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplican', 'Por meio desta, fica registrado que, no dia 08/02/2025, Vossa Senhoria abandonou o posto de trabalho', 'Advertencia  abandono de veículo.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (26, 'Advertencia - abastecimento em postos não credenciado', 'advertencia', 'Esta advertência refere-se ao descumprimento das diretrizes estabelecidas pela empresa quanto ao abastecimento de veículos em postos credenciados. Conforme orientado previamente, todos os veículos da empresa devem ser abastecidos exclusivamente em postos previamente autorizados e credenciados. No entanto, 04/11/2024, constatamos que o veículo sob sua responsabilidade placa FCW9708 foi abastecido em um posto não autorizado. Ressaltamos que, na ocasião, o Sr(a). teve a oportunidade de abastecer em um posto credenciado, mas não seguiu as instruções estabelecidas. Esse procedimento é fundamental para assegurar a qualidade dos combustíveis utilizados, além de contribuir com a segurança e a economia nas operações da empresa. O não cumprimento das normas internas compromete tanto os processos quanto os recursos da organização. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao prin', 'Esta advertência refere-se ao descumprimento das diretrizes estabelecidas pela empresa quanto ao aba', 'Advertencia - abastecimento em postos não credenciado.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (27, 'Advertencia - autodeclaração', 'advertencia', 'Considerando que Vossa Senhoria se recursou a preencher a autodeclararão, solicitada pela empresa, para atender à exigência do art. 39, § 8º, da Lei nº 12.288/2010, alterado pela Lei nº 14.553/2023 e da Portaria MTE nº 3.784/2023, que obriga a prestação da informação nas inclusões, alterações ou retificações cadastrais dos trabalhadores ocorridas a partir de 1ª de janeiro de 2024. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar advertência, pela prática do disposto na alínea “h” do Art. 482 da CLT (insubordinação).', 'Considerando que Vossa Senhoria se recursou a preencher a autodeclararão, solicitada pela empresa, p', 'Advertencia - autodeclaração.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (28, 'Advertencia - pena seca falta de diessel', 'advertencia', 'Considerando que Vossa Pessoa, na condição de motorista profissional, responsável pelo veículo placa (     ) apresentou comportamento inadequado, no dia 09/10/2024, retornou do cliente carregado, encostou a carreta no pátio da BRF e não se atentou em verificar o nível de combustível  do termo king do equipamento de refrigeração e tampouco comunicou alguém, a carreta apresentou pane seca por falta de combustível, colocando em risco a mercadoria que tem o valor de R$ 211.070,07. atitude está inaceitável e inadmissível por esta empresa.  Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar advertência, pela prática do disposto na alínea “E e H” do Art. 482 da CLT (dissidia e indisciplina).', 'Considerando que Vossa Pessoa, na condição de motorista profissional, responsável pelo veículo placa', 'Advertencia - pena seca falta de diessel.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (29, 'Advertencia - prejuizos', 'advertencia', 'Estamos emitindo esta advertência formal devido ao ocorrido no dia 16/10/2024em que foi constatado que você permitiu que outra pessoa realizasse suas atividades de responsabilidade, resultando em danos no puxador da porta do baú Ressaltamos que, conforme as normas e políticas internas da nossa empresa, cada colaborador é responsável por executar suas próprias tarefas e por garantir que suas funções sejam realizadas com competência e profissionalismo. Ao delegar suas responsabilidades para terceiros sem autorização, você não só violou os procedimentos internos, mas também causou prejuízos que impactaram negativamente nossa operação. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Em face do corrido, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “e” do', 'Estamos emitindo esta advertência formal devido ao ocorrido no dia 16/10/2024em que foi constatado q', 'Advertencia - prejuizos.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (30, 'Advertencia canhoto digital', 'advertencia', 'A empresa Transportes Framento, no exercício do seu poder diretivo e disciplinar, com fundamento no artigo 2º da Consolidação das Leis do Trabalho (CLT), bem como nos termos do artigo 482, alíneas “h” (ato de indisciplina) e “k” (descumprimento das normas da empresa ou ordens de serviço), vem, por meio desta, aplicar advertência disciplinar a Vossa Senhoria. Conforme apurado, vossa senhoria deixou reiteradamente de realizar o registro do canhoto digital, procedimento obrigatório exigido por cliente da empresa, e proferiu palavras de baixo calão dirigidas ao seu superior hierárquico, demonstrando conduta incompatível com o ambiente profissional e as normas internas da organização. Tal comportamento caracteriza ato de insubordinação e descumprimento deliberado de ordens e procedimentos operacionais, comprometendo a disciplina no ambiente de trabalho e a imagem institucional da empresa junto aos seus contratantes. Ressaltamos que atitudes como essa violam as políticas internas e, em caso ', 'A empresa Transportes Framento, no exercício do seu poder diretivo e disciplinar, com fundamento no ', 'Advertencia canhoto digital.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (31, 'Advertencia direção continua', 'advertencia', 'Por meio desta, vimos aplicar-lhe ADVERTÊNCIA ESCRITA, tendo em vista o fato ocorrido no dia 13/06/2025, em que Vossa Senhoria conduziu veículo de propriedade desta empresa por mais de 10 (dez) horas ininterruptas, sem qualquer parada ou descanso. Tal conduta configura infração grave às normas internas da empresa, bem como desrespeito direto à legislação trabalhista e de trânsito, colocando em risco sua integridade física, a segurança pública e o patrimônio da empresa. Fundamentação Jurídica: CLT – Consolidação das Leis do Trabalho Art. 235-C, § 2º da CLT (após a Lei 13.103/2015): “A jornada de trabalho do motorista profissional será de até 8 (oito) horas diárias, podendo ser prorrogada por até 2 (duas) horas extraordinárias ou, mediante previsão em convenção ou acordo coletivo, por até 4 (quatro) horas extras.” § 3º: “É vedada a condução do veículo por mais de 5 (cinco) horas e meia ininterruptas.” § 4º: “Após 5 (cinco) horas e meia de direção, é assegurado ao motorista um intervalo m', 'Por meio desta, vimos aplicar-lhe ADVERTÊNCIA ESCRITA, tendo em vista o fato ocorrido no dia 13/06/2', 'Advertencia direção continua.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (32, 'Advertencia horas extras sem autorização', 'advertencia', ' Em 19 de setembro de 2025, o empregado acima identificado, apesar de expressa determinação do gestor imediato para retornar ao Centro de Distribuição com a carga transportada, optou por descumprir a ordem, finalizando integralmente as entregas programadas. Tal conduta ocasionou a prestação de mais de 5 (cinco) horas extras não autorizadas, comprometendo o intervalo interjornadas mínimo de 11 (onze) horas, gerando custos operacionais desnecessários e expondo a empresa a riscos de fiscalização e passivos trabalhistas. A conduta caracteriza dissidia e ato de insubordinação, conforme previsão do art. 482, alínea “h”, da CLT. Fundamentam a presente advertência: Art. 58 e 59 da CLT – Limitação da jornada e necessidade de prévia autorização para horas extraordinárias; Art. 66 da CLT – Intervalo interjornadas mínimo de 11 (onze) horas; Art. 71 da CLT – Garantia de intervalo para repouso e alimentação; Decisão do STF na ADI 5322 – Reforça a obrigatoriedade do intervalo mínimo interjornadas e a', ' Em 19 de setembro de 2025, o empregado acima identificado, apesar de expressa determinação do gesto', 'Advertencia horas extras sem autorização.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (33, 'Advertencia motivos gerais', 'advertencia', 'Esta notificação refere-se a infrações observadas em relação às normas e regulamentos da nossa empresa, conforme o que foi previamente comunicado e acordado com todos os colaboradores. Em específico, foram identificados os seguintes comportamentos: Excesso de Velocidade Permitida: Constatamos que você excedeu o limite de velocidade permitido nas dependências da empresa / em atividade de deslocamento pela empresa. Esse comportamento coloca em risco sua segurança, a de seus colegas e a integridade dos ativos da empresa. Não Cumprimento das Normas da Empresa: Este incidente é uma violação dos regulamentos de segurança e dos padrões de conduta que todos os colaboradores devem respeitar. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando as faltas injustiçadas, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade ', 'Esta notificação refere-se a infrações observadas em relação às normas e regulamentos da nossa empre', 'Advertencia motivos gerais.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (34, 'Advertencia palavras de baixo calao', 'advertencia', 'Por meio desta, comunicamos que Vossa Senhoria incorreu em conduta inadequada no ambiente de trabalho, ao verbalizar palavras de baixo calão e desrespeitosas dirigidas a seu gestor imediato, no dia 13/05/2025, durante o expediente. Tal conduta infringe as normas internas de convivência da empresa e os princípios de respeito mútuo entre os colaboradores e seus superiores hierárquicos, sendo incompatível com o ambiente de trabalho saudável e produtivo que buscamos manter. Esta advertência fundamenta-se no artigo 482, alínea “h”, da Consolidação das Leis do Trabalho (CLT), que prevê como justa causa para rescisão contratual o "ato de indisciplina ou de insubordinação", sendo esta advertência uma medida disciplinar preliminar com a finalidade de corrigir o comportamento inadequado. Ressaltamos que a repetição de condutas semelhantes poderá ensejar medidas disciplinares mais severas, nos termos da legislação vigente. Solicitamos que Vossa Senhoria tome ciência desta advertência, ciente de q', 'Por meio desta, comunicamos que Vossa Senhoria incorreu em conduta inadequada no ambiente de trabalh', 'Advertencia palavras de baixo calao.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (35, 'Advertencia perda de diária', 'advertencia', 'Por meio desta, a empresa Transportes Framento, aplica-lhe a presente advertência disciplinar devido ao descumprimento de suas responsabilidades funcionais no dia 17/03/2025. Foi constatado que, após a descarga do veículo de propriedade da empresa placa LMP4J37, Vossa Senhoria não retornou ao cliente para carregamento, ocasionando corte de diária para a Transportes Framento. Além disso, não comunicou seu programador sobre a realização de manutenção do veículo, o que gerou transtornos na operação e impactou negativamente a imagem da empresa perante o embarcador. A empresa reforça a importância do cumprimento dos procedimentos internos e da comunicação eficaz para evitar prejuízos operacionais e danos à reputação da organização. Ressaltamos que a reincidência de condutas similares poderá resultar na aplicação de sanções mais severas, conforme previsto nas normas internas da empresa e na legislação vigente. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as dilig', 'Por meio desta, a empresa Transportes Framento, aplica-lhe a presente advertência disciplinar devido', 'Advertencia perda de diária.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (36, 'Advertencia pernoite', 'advertencia', 'Considerando que Vossa Pessoa, na condição de motorista profissional, já orientado por inúmeras vezes pela equipe de jornada e gestão, responsável pelo veículo (Placa  FRR9D56) foi negligente no desempenho das suas funções no dia 11/10/2024 para 12/10/2024 por não ter cumprindo o descanso interjornada, e ao ser parado pela PRF sofreu multa,  tais atitudes são inadmissíveis e inaceitáveis pela empresa Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “ h ” do Art. 482 da CLT (indisciplina e insubordinação).', 'Considerando que Vossa Pessoa, na condição de motorista profissional, já orientado por inúmeras veze', 'Advertencia pernoite.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (37, 'Advertencia por abandonar o caminhã e marcar a jornada', 'advertencia', 'Vossa Senhoria, na condição de motorista profissional desta empresa, no dia 29/02/2025, abandonou o caminhão de placa GDP-3533, deixando-o dentro do embarcador Marfrig, e ausentou-se do local de trabalho para dirigir-se à sua residência sem prévia comunicação ou autorização do gestor responsável. Além disso, constatou-se que Vossa Senhoria registrou sua jornada de trabalho sem efetivamente prestar os serviços devidos, o que configura conduta inadequada e prejudicial à operação da empresa. Diante dos fatos, informamos que sua conduta infringe as normas internas da empresa e a legislação trabalhista, especialmente: CLT - Consolidação das Leis do Trabalho: Artigo 482, alíneas "e" e "h" – Configurações de atos de desídia e insubordinação. Artigo 58, §1º – Obrigação do cumprimento da jornada de trabalho estabelecida. Lei 13.103/2015 (Lei do Motorista): Artigo 10 – Obrigações do motorista profissional no cumprimento da jornada e zelo pelo veículo. Diante do exposto, esta advertência formal v', 'Vossa Senhoria, na condição de motorista profissional desta empresa, no dia 29/02/2025, abandonou o ', 'Advertencia por abandonar o caminhã e marcar a jornada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (38, 'Advertencia por abandonar o posto de trabalho e se recusar em viajar', 'advertencia', 'Através deste, vimos formalmente adverti-lo pelos fatos ocorridos no dia 11 de julho de 2025, quando, na condição de motorista profissional, Vossa Senhoria recusou-se a realizar viagem programada e, sem qualquer consentimento ou autorização de seu gestor imediato, dirigiu-se à sua residência durante o expediente de trabalho. Tal conduta caracteriza-se como ato de insubordinação e abandono de posto de trabalho, violando diretamente os deveres do empregado previstos no artigo 482, alínea “h” e “e” da Consolidação das Leis do Trabalho (CLT), que estabelece como motivos para penalidade a insubordinação, além da desídia no desempenho das respectivas funções. Além disso, o comportamento adotado infringe o princípio da boa-fé objetiva (art. 422 do Código Civil) e compromete a confiança necessária na relação de emprego, bem como prejudica a organização e o funcionamento regular da operação logística da empresa, gerando transtornos operacionais relevantes. Dessa forma, fica Vossa Senhoria adver', 'Através deste, vimos formalmente adverti-lo pelos fatos ocorridos no dia 11 de julho de 2025, quando', 'Advertencia por abandonar o posto de trabalho e se recusar em viajar.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (39, 'Advertencia por abandono do posto de trabalho', 'advertencia', 'ADVERTÊNCIA POR ABANDONO DO POSTO DE TRABALHO E IRREGULARIDADE NO REGISTRO DE JORNADA A Transportes Framento, na qualidade de empregadora, vem por meio desta adverti-lo formalmente em razão de conduta incompatível com as obrigações decorrentes de seu contrato de trabalho e com a disciplina interna da empresa. Foi apurado que, no sábado, dia 19/07/2025, por volta das 13h00, Vossa Senhoria, na condição de motorista responsável pelo veículo de placa TUD0F93, abandonou o caminhão estacionado na doca do embarcador Coop, ausentando-se do local de trabalho sem qualquer comunicação prévia ou autorização do gestor imediato, sendo que a jornada de trabalho regular se encerraria apenas às 16h00. Além disso, deixou a jornada aberta no sistema, o que gerou registro indevido de horas extras não laboradas, contrariando normas internas e configurando infração disciplinar. Tal conduta fere gravemente os deveres previstos nos arts. 482, alínea “e” e “h”, e art  3º da CLT, que impõem ao empregado o dever', 'ADVERTÊNCIA POR ABANDONO DO POSTO DE TRABALHO E IRREGULARIDADE NO REGISTRO DE JORNADA A Transportes ', 'Advertencia por abandono do posto de trabalho.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (40, 'Advertencia por agreções', 'advertencia', 'NILSON RODRIGUES FERREIRA empresa Transportes Framento Ltda., na qualidade de empregadora e no exercício regular de seu poder diretivo e disciplinar, conforme previsto no art. 2º da Consolidação das Leis do Trabalho (CLT), vem, por meio desta, aplicar advertência disciplinar em razão de conduta incompatível com as normas internas da empresa e com a legislação vigente. Conforme apurado, na data de 07/09/2025, Vossa Senhoria saiu em viagem do Embu das Artes – SP, com destino a Várzea Grande – MT, às 06h47. Por volta das 17h00, ao chegar em Promissão – SP, estacionou o veículo no posto e encerrou sua jornada. Durante esse período, por volta das 18h00, ocorreu um confronto físico com o Sr. Rodnei D’Angelo (CPF: 227.523.088-25), funcionário em folga desde 06/09, resultando em lesão em seu braço. Tal conduta configura desrespeito às normas internas de conduta e segurança da empresa, além de prática de ato de agressão física, o que pode ser enquadrado como infração disciplinar grave, nos term', 'NILSON RODRIGUES FERREIRA empresa Transportes Framento Ltda., na qualidade de empregadora e no exerc', 'Advertencia por agreções.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (41, 'Advertencia por atraso na devolução dos pallets', 'advertencia', 'Por meio desta, notificamos que Vossa Senhoria descumpriu as normas internas do embarcador BRF ao não devolver os pallets no prazo estabelecido. Além disso, foi constatado que o veículo de propriedade da empresa, placa FRD8124, não foi utilizado com o devido zelo, contrariando as diretrizes de conservação patrimonial. Diante do exposto, esta advertência tem o objetivo de reforçar a necessidade de cumprimento das regras internas e do cuidado adequado com os bens da empresa. O não atendimento a essas diretrizes poderá resultar em medidas disciplinares mais severas. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “E” do Art. 482 da CLT (dissidia).', 'Por meio desta, notificamos que Vossa Senhoria descumpriu as normas internas do embarcador BRF ao nã', 'Advertencia por atraso na devolução dos pallets.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (42, 'Advertencia por auntar-se do trabalho', 'advertencia', 'Na qualidade de motorista profissional, vinculado ao quadro funcional da empresa Transportes Framento, vimos, por meio desta, formalizar ADVERTÊNCIA DISCIPLINAR, com fundamento no artigo 482, alínea “e” e “h”, da Consolidação das Leis do Trabalho (CLT), que autoriza a aplicação de sanções em razão de ato de indisciplina. Consta em registro interno que, no dia 25 de julho de 2025, Vossa Senhoria, durante o horário regular de expediente, deixou de cumprir ordem direta do gestor imediato, ao se dirigir para sua residência sem prévia autorização, deixando de realizar a atividade previamente determinada, qual seja, o encaminhamento de veículo da frota para manutenção programada. Tal conduta caracteriza-se como descumprimento injustificado de instrução superior e quebra de dever funcional, em desacordo com os princípios da subordinação hierárquica e da boa-fé objetiva, comprometendo a organização logística da empresa, além de causar prejuízos operacionais. Advertimos que reincidências em con', 'Na qualidade de motorista profissional, vinculado ao quadro funcional da empresa Transportes Frament', 'Advertencia por auntar-se do trabalho.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (43, 'Advertencia por bater na doca', 'advertencia', 'Prezado Senhor, A presente serve para formalizar uma ADVERTÊNCIA em seu prontuário funcional, em virtude do ocorrido no dia 16/05/2025, quando Vossa Senhoria, na condição de motorista profissional desta empresa, ao manobrar o veículo de propriedade da Transportes Framento, conjunto de placas GKA1I61 e MMA4843, colidiu a carreta na doca, gerando danos materiais. Constatou-se que a colisão ocorreu por falta da devida atenção durante a manobra do veículo, conduta incompatível com as responsabilidades e o cuidado esperado de um profissional da condução, especialmente no manuseio de veículos de grande porte pertencentes à empresa. FUNDAMENTAÇÃO JURÍDICA: A presente advertência tem como fundamento jurídico, em especial: Artigo 482, alínea "h", da Consolidação das Leis do Trabalho (CLT): que prevê como justa causa para rescisão do contrato de trabalho, por parte do empregador, o ato de negligência do empregado que resulte em prejuízo ao empregador. Embora a presente seja uma advertência, este', 'Prezado Senhor, A presente serve para formalizar uma ADVERTÊNCIA em seu prontuário funcional, em vir', 'Advertencia por bater na doca.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (44, 'Advertencia por bloqueio faixa amarela', 'advertencia', 'Esta advertência tem o objetivo de informar e registrar uma infração grave às normas de segurança da Transportes Framento e dos procedimentos exigidos pelo embarcador BRF. No dia 11/12/2024 foi constatado que vossa Senhoria estava utilizando o celular enquanto conduzia o veículo placa SRZ9880, o que resultou em uma infração grave levando-o ao bloqueio de acesso na faixa amarela do embarcador. O uso de dispositivos móveis durante a condução representa um risco à segurança de todos.  De acordo com as normas internas e as regras de segurança vigentes no embarcador, o uso de celular durante a condução é expressamente proibido. Essa ação é considerada uma violação grave das diretrizes de segurança que a empresa adota para proteger a integridade física dos colaboradores, parceiros e do ambiente de trabalho como um todo. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio ', 'Esta advertência tem o objetivo de informar e registrar uma infração grave às normas de segurança da', 'Advertencia por bloqueio faixa amarela.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (45, 'Advertencia por conceder carrona', 'advertencia', 'Por meio desta, a Framento Transportes, vem formalmente adverti-lo em razão do descumprimento das normas internas da empresa e do cliente BRF. Conforme apurado, no dia 13/02/2025, Vossa Senhoria, na condição de motorista profissional e responsável pelo veículo de propriedade da empresa, conjunto de placa EHC0H34/MJQ9075, transportou sua esposa como carona no referido veículo, que é dedicado ao embarcador BRF. Tal conduta contraria as diretrizes da BRF e as normas internas da Framento, as quais proíbem expressamente o transporte de terceiros sem autorização prévia. Ressaltamos que o descumprimento dessas regras compromete a segurança operacional, podendo gerar consequências mais severas em caso de reincidência. Em face de vossa atitude o embarcador proibiu nossa senhoria de entrar no condomínio, o qual foi necessária uma força tarefa para conseguir restabelecer vosso acesso as dependências do embarcador. Solicitamos que se atente ao cumprimento rigoroso das normas e procedimentos da emp', 'Por meio desta, a Framento Transportes, vem formalmente adverti-lo em razão do descumprimento das no', 'Advertencia por conceder carrona.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (46, 'Advertencia por danificar tablet', 'advertencia', 'Na qualidade de colaborador da empresa Transportes Framento, comunicamos, por meio desta, a aplicação de advertência disciplinar em razão de conduta incompatível com as normas internas da empresa e com os deveres decorrentes do contrato de trabalho. Conforme apurado, Vossa Senhoria, de forma imprudente e irresponsável, danificou o tablet fixado na cabine da carreta, sob a alegação de estar recebendo mensagens no referido dispositivo. Tal atitude ocasionou prejuízos financeiros à empresa, além de transtornos operacionais, com a necessidade de interrupção das atividades para reparo do equipamento. Ressaltamos que a empresa disponibiliza equipamentos de trabalho com o intuito de garantir a segurança e a eficiência das atividades desempenhadas. A má utilização e o descuido com o patrimônio da empresa configuram infração contratual, passível de sanção disciplinar, nos termos do art. 482, alíneas “b” e “h” da Consolidação das Leis do Trabalho (CLT), que tratam do mau procedimento e da indisc', 'Na qualidade de colaborador da empresa Transportes Framento, comunicamos, por meio desta, a aplicaçã', 'Advertencia por danificar tablet.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (47, 'Advertencia por deixar faltar combustivel no veiculo (1)', 'advertencia', 'Ricardo da silva moreira Considerando que, no dia 04/02/2025, Vossa Senhoria deixou de abastecer o veículo de propriedade da empresa, placa FAU1116, resultando na falta de óleo diesel e gerando inúmeros transtornos na operação, vimos por meio desta aplicar-lhe advertência. O descumprimento das responsabilidades inerentes à função pode acarretar prejuízos ao desempenho das atividades da empresa. Dessa forma, solicitamos que redobre a atenção para evitar a repetição dessa situação. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “E” do Art. 482 da CLT.', 'Ricardo da silva moreira Considerando que, no dia 04/02/2025, Vossa Senhoria deixou de abastecer o v', 'Advertencia por deixar faltar combustivel no veiculo (1).docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (48, 'Advertencia por descumprir as regras do PGR', 'advertencia', 'Considerando que Vossa Pessoa, na condição de motorista profissional, responsável pelo veículo (placa-----------), haver descumprindo as regras do PGR, e das normas da empresa, saindo do CD sem a liberação da seguradora na data 17/07/2024.  Considerando que, o comportamento de Vossa Senhoria foi um ato de insubordinação, exponto a empresa em riscos desnecessários, por não cumprir as políticas da empresa e ignorar as orientações repassadas, o que justifica a presente advertência  Considerando também, este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando as transgressões cometida, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “h” do Art. 482 da CLT (Insubordinação)', 'Considerando que Vossa Pessoa, na condição de motorista profissional, responsável pelo veículo (plac', 'Advertencia por descumprir as regras do PGR.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (49, 'Advertencia por desrespeito', 'advertencia', 'Por meio deste documento, formalizamos a aplicação de advertência em razão das seguintes ocorrências: Procedimentos operacionais: No dia ----/----/----- foi constatado que você deixou de realizar o procedimento obrigatório de fechamento do canhoto no caixa, contrariando os processos internos da Seara Alimentos, os quais foram previamente comunicados e são essenciais para o controle e organização das atividades. Conduta inadequada: Ainda no mesmo período, foi identificado um episódio de desrespeito ao gestor da Framento, no qual foram proferidas palavras de baixo calão, demonstrando comportamento incompatível com as normas de conduta e ética estabelecidas pela empresa. Essas atitudes violam o Código de Conduta da empresa e os princípios que norteiam o ambiente de trabalho respeitoso e profissional. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade d', 'Por meio deste documento, formalizamos a aplicação de advertência em razão das seguintes ocorrências', 'Advertencia por desrespeito.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (50, 'Advertencia por dissidia atrassos', 'advertencia', 'Vossa Senhoria, desde o dia 31 de março de 2025, vem se apresentando ao trabalho com recorrentes atrasos injustificados. Ressaltamos que, em razão desses atrasos, no dia 31 de março de 2024, houve perda de agenda com o embarcador BRF, ocasionando prejuízo financeiro à empresa, que arcou com o desconto de uma diária no valor de R$ 1.313,23. Além do impacto financeiro, os constantes atrasos vêm prejudicando a imagem da empresa Framento perante o embarcador BRF e comprometendo o cumprimento das metas contratuais assumidas com o referido parceiro comercial. Tal conduta infringe o art. 482, alínea “e”, da Consolidação das Leis do Trabalho (CLT), que dispõe sobre a possibilidade de penalidade ao empregado por desídia no desempenho de suas funções. A recorrência em atrasos caracteriza descumprimento de deveres funcionais e pode ensejar medidas disciplinares mais severas, caso não haja imediata correção da conduta. Diante do exposto, esta advertência tem por finalidade registrar formalmente o ', 'Vossa Senhoria, desde o dia 31 de março de 2025, vem se apresentando ao trabalho com recorrentes atr', 'Advertencia por dissidia atrassos.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (51, 'Advertencia por dissionada - jornada aberta', 'advertencia', 'Considerando que Vossa Pessoa, na condição de motorista profissional, responsável pelo veículo (Placa  ), foi negligente no desempenho das suas funções nos dias    28/09/2024, não acatar as orientações da equipe de controle jornada no que tange abertura da jornada e pernoite, além se exaltar e afinar que vai continuar fazendo da forma que acha correta, atitude esta inaceitável e inadmissível por esta empresa.   Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os prejuízos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de suspensão de 3 dias, sem remuneração e DSR, pela prática do disposto na alínea “ H” do Art. 482 da CLT, indisciplina, no desempenho das respectivas funções.', 'Considerando que Vossa Pessoa, na condição de motorista profissional, responsável pelo veículo (Plac', 'Advertencia por dissionada - jornada aberta.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (52, 'Advertencia por encerrar a jornada', 'advertencia', 'Vossa Senhoria, no dia 18/03/2025, encerrou sua jornada de trabalho antes do horário previsto e deixou as dependências do cliente sem prévia comunicação e sem apresentar qualquer justificativa válida para tal conduta. Tal atitude contraria as normas internas da empresa e compromete o bom andamento das atividades, podendo gerar impactos negativos na prestação de serviços ao cliente. Dessa forma, fica registrado o presente documento como advertência formal. Reiteramos a importância do cumprimento dos horários estabelecidos e da comunicação adequada em casos de necessidade de alteração na jornada. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de suspensão por 2 (dois) dia sem remuneração, pela prática do d', 'Vossa Senhoria, no dia 18/03/2025, encerrou sua jornada de trabalho antes do horário previsto e deix', 'Advertencia por encerrar a jornada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (53, 'Advertencia por excesso de horas extras sem necessidade', 'advertencia', 'Serve a presente para adverti-lo formalmente pelo descumprimento das normas legais e internas relativas à jornada de trabalho e ao tempo de descanso obrigatório do motorista profissional. Conforme registros de controle de jornada do dia 31/08/2025, Vossa Senhoria não dirigiu nesse dia, contudo, excedeu a jornada legal de 01:42 (uma hora e quarenta e dois minutos) de horas extras desnecessárias, sem justificativa operacional ou autorização superior. Além disso, foi verificado o prejuízo ao descanso mínimo obrigatório de 11 (onze) horas ininterruptas entre jornadas, em desacordo com o previsto no artigo 235-C, § 2º, da Lei nº 13.103/2015 (Lei do Motorista), e em desrespeito à decisão do Supremo Tribunal Federal na Ação Direta de Inconstitucionalidade (ADI) 5322, que reconheceu a constitucionalidade do referido descanso mínimo, reforçando sua obrigatoriedade. Art. 482, alínea “e” e “h”: Constituem justa causa para rescisão do contrato de trabalho pelo empregador dissidia e ato de indiscip', 'Serve a presente para adverti-lo formalmente pelo descumprimento das normas legais e internas relati', 'Advertencia por excesso de horas extras sem necessidade.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (54, 'Advertencia por excesso de jormada e horas extras', 'advertencia', 'A Transportes Framento, na qualidade de empregadora e no exercício regular de seu poder diretivo e disciplinar previsto no art.2º da CLT, ADVERTE FORMALMENTE Vossa Senhoria, na condição de motorista profissional, pelos seguintes fatos: No dia 14/09/2025, foi constatado que vossa senhoria excedeu a jornada normal de trabalho em 45 (quarenta e cinco) minutos, realizando horas extras sem a devida autorização prévia e sem necessidade operacional. Tal conduta afronta: Artigo 58 da Consolidação das Leis do Trabalho (CLT), que disciplinam a jornada de trabalho e a subordinação ao poder diretivo do empregador; Art. 59 da CLT, que condiciona a prorrogação da jornada à prévia autorização; Lei nº 13.103/2015 (Lei do Motorista Profissional) e ADI 5322 do STF, que estabelecem a observância dos limites de jornada e períodos de descanso, visando à saúde e segurança do trabalhador. Diante disso, está advertência tem caráter disciplinar e preventivo, servindo de registro formal para que situações semel', 'A Transportes Framento, na qualidade de empregadora e no exercício regular de seu poder diretivo e d', 'Advertencia por excesso de jormada e horas extras.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (55, 'Advertencia por excesso de jornada aberta e gerando horas extras', 'advertencia', 'A empresa TRANSPORTES FRAMENTO LTDA, por meio de seu representante legal, no exercício regular do poder diretivo e disciplinar que lhe confere o artigo 2º da Consolidação das Leis do Trabalho (CLT), bem como em conformidade com o dever de obediência às normas internas previsto no artigo 482, alíneas “e” e “h” da CLT, vem, por meio desta, aplicar a presente ADVERTÊNCIA ESCRITA, a vossa senhoria, que exercer a função de Motorista Profissional, pelos fatos a seguir descritos: No dia 25/08/2025, na condução do veículo de propriedade da empresa, placa EGT4E81, Vossa Senhoria deixou a jornada de trabalho aberta por 14 horas e 53 minutos, sem realizar o intervalo para refeição, bem como prejudicando o intervalo interjornada de 11 (onze) horas, em descumprimento ao disposto na Lei nº 13.103/2015 (Lei do Motorista) e à interpretação consolidada na ADI 5322 do Supremo Tribunal Federal. Tal conduta resultou na geração de horas extras desnecessárias e não autorizadas, trazendo riscos de autuações ', 'A empresa TRANSPORTES FRAMENTO LTDA, por meio de seu representante legal, no exercício regular do po', 'Advertencia por excesso de jornada aberta e gerando horas extras.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (56, 'Advertencia por excesso de jornada não autorizada', 'advertencia', 'No dia 14/09/2025, Vossa Senhoria, na condição de motorista profissional, deixou de realizar o intervalo destinado à alimentação e descanso, extrapolando a jornada normal de 8 (oito) horas em 2 (duas) horas extras sem necessidade operacional. Tal conduta comprometeu o intervalo mínimo para repouso previsto em lei, além de descumprir orientações internas previamente repassadas. Fundamentação Jurídica: – Consolidação das Leis do Trabalho (CLT), art. 71 – garante o intervalo mínimo para repouso e alimentação; – CLT, art. 58  – estabelece a duração da jornada normal; – Lei nº 13.103/2015 (Lei do Motorista Profissional), art. 235-C, §3º – dispõe sobre o intervalo obrigatório para refeição e descanso; – Decisão do STF na ADI 5322 – reforça a obrigatoriedade e irrenunciabilidade dos intervalos de descanso; – CLT, art. 2º e 482, alínea “e” e “h” – confere ao empregador o poder disciplinar para aplicar medidas cabíveis diante de desídia, indisciplina e/ou descumprimento de normas  Diante da inf', 'No dia 14/09/2025, Vossa Senhoria, na condição de motorista profissional, deixou de realizar o inter', 'Advertencia por excesso de jornada não autorizada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (57, 'Advertencia por excesso de jornada', 'advertencia', 'Após análise do controle de jornada, foi constatado que, no dia 03/07/2025, Vossa Senhoria iniciou a jornada de trabalho às 09h25 e somente a encerrou no dia 04/07/2025 às 22h19, totalizando 36 horas e 52 minutos ininterruptos de jornada, o que ultrapassa amplamente os limites legais permitidos. Adicionalmente, verificou-se que após encerrar a jornada às 22h19 do dia 04/07/2025, reabriu nova jornada às 22h34, ou seja, após apenas 15 minutos de intervalo, o que configura descumprimento grave das normas legais sobre descanso obrigatório entre jornadas. Nos termos do Art. 235-C da Consolidação das Leis do Trabalho (CLT), incluído pela Lei nº 13.103/2015 (Lei do Motorista), o motorista profissional tem direito ao descanso obrigatório de 11 (onze) horas dentro de cada período de 24 horas, bem como descanso entre jornadas de no mínimo 11 horas consecutivas. Desta forma, a conduta observada no período em questão representa grave violação das normas legais de saúde e segurança do trabalho, col', 'Após análise do controle de jornada, foi constatado que, no dia 03/07/2025, Vossa Senhoria iniciou a', 'Advertencia por excesso de jornada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (58, 'Advertencia por excesso de jornadas', 'advertencia', 'A empresa Transportes Framento, na qualidade de empregadora e no exercício regular de seu poder diretivo e disciplinar, previsto no art. 2º da Consolidação das Leis do Trabalho (CLT), vem por meio desta advertir formalmente Vossa Senhoria pelas infrações cometidas durante a jornada de trabalho do dia 05 de agosto de 2025. De acordo com os registros de jornada, Vossa Senhoria iniciou as atividades às 04h05 do dia 05/08/2025 e encerrou às 01h53 do dia 06/08/2025, totalizando uma jornada de 20 horas e 38 minutos, sendo 19 horas e 33 minutos de tempo efetivo de direção ao longo de diversas sessões. Ressalta-se que o maior tempo contínuo de parada foi de apenas 34 minutos, e o período total de descanso (pernoite) foi de 7 horas e 15 minutos, em descumprimento aos limites legais de jornada e repouso. Tais condutas configuram ato de indisciplina, nos termos do art. 482, alínea “h” da CLT, e violam as normas de saúde, segurança e regulação da jornada de trabalho previstas na Lei nº 13.103/2015', 'A empresa Transportes Framento, na qualidade de empregadora e no exercício regular de seu poder dire', 'Advertencia por excesso de jornadas.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (59, 'Advertencia por falta ao trabalho injustificada', 'advertencia', 'No exercício regular do poder diretivo e disciplinar conferido pelo artigo 2º da Consolidação das Leis do Trabalho (CLT) e em observância ao artigo 482, alínea “e”, da CLT, que prevê como falta grave as ausências injustificadas, a empresa ADVERTE FORMALMENTE Vossa Senhoria pelos seguintes fatos: No dia 2/09/2025, vossa senhoria ausentou-se do trabalho sem apresentar qualquer justificativa, conduta que já ocorreu em outras oportunidades e pela qual recebeu advertência verbal de seu gestor imediato. Ressaltamos que a reincidência em ausências injustificadas configura desídia, podendo ensejar sanções mais severas, inclusive suspensão ou rescisão contratual por justa causa, conforme previsão legal supracitada. Salienta-se, ainda, que a presente medida está sendo adotada em observância ao princípio da imediatidade. Solicita-se que Vossa Senhoria assine o presente documento, declarando ciência de seu conteúdo. Em caso de recusa, a empresa providenciará o registro da entrega mediante assinatu', 'No exercício regular do poder diretivo e disciplinar conferido pelo artigo 2º da Consolidação das Le', 'Advertencia por falta ao trabalho injustificada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (60, 'Advertencia por faltas injustificada', 'advertencia', 'Por meio deste, comunicamos que, no dia28 de junho de 2025, foi constatada a sua ausência ao trabalho sem qualquer justificativa prévia ou posterior, em descumprimento ao seu contrato de trabalho e às normas internas da empresa. Tal conduta gerou prejuízos à operação do setor, comprometendo o andamento das atividades e afetando a produtividade da equipe. Informamos que esta conduta infringe o artigo 482 da Consolidação das Leis do Trabalho (CLT), que trata das justas causas para rescisão do contrato de trabalho, especialmente no que tange à alínea “e”, que trata da desídia no desempenho das respectivas funções. Ressaltamos também o dever de assiduidade e pontualidade previsto no artigo 158, § único, combinado com o artigo 444 da CLT. Diante do exposto, esta advertência tem como objetivo alertá-lo(a) formalmente sobre a irregularidade cometida, visando à correção de condutas futuras. A reincidência poderá acarretar medidas disciplinares mais severas, conforme previsto na legislação vige', 'Por meio deste, comunicamos que, no dia28 de junho de 2025, foi constatada a sua ausência ao trabalh', 'Advertencia por faltas injustificada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (61, 'Advertencia por insubordinação - excesso de velocidade', 'advertencia', 'Considerando que Vossa Pessoa, na condição de motorista profissional, responsável pelo veículo (Placa MIB2354), foi negligente no desempenho das suas funções nos dias   23, 24    /08/2024, por exceder os limites de velocidade chegando a 84km/h o que é contrário às regras da empregadora, atitude esta inaceitável e inadmissível por esta empresa.   Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os prejuízos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de suspensão de 3 dias, sem remuneração e DSR, pela prática do disposto na alínea “E e H” do Art. 482 da CLT, desídia e indisciplina, no desempenho das respectivas funções.', 'Considerando que Vossa Pessoa, na condição de motorista profissional, responsável pelo veículo (Plac', 'Advertencia por insubordinação - excesso de velocidade.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (62, 'Advertencia por insubordinação', 'advertencia', 'Vossa Senhoria, na condição de motorista profissional, vem reiteradamente apresentando falta de urbanidade no ambiente de trabalho, manifestando comportamentos desrespeitosos e inadequados para com seu gestor imediato, contrariando as normas internas de conduta e desrespeitando os princípios básicos do convívio profissional. Esclarecemos que tal conduta é inadmissível e infringe os deveres do empregado previstos no art. 482, alínea " E e H", da Consolidação das Leis do Trabalho (CLT), que dispõe sobre a possibilidade de punição por ato de dissidia e insubordinação. Além disso, viola os princípios da boa-fé contratual e do respeito mútuo, que devem reger a relação de trabalho (art. 422 do Código Civil). Informamos que a reincidência de tais atitudes poderá ensejar a aplicação de sanções mais severas, conforme a gradação da pena prevista na legislação vigente e nas normas internas da empresa, podendo inclusive resultar em suspensão ou dispensa por justa causa, se persistirem as condutas ', 'Vossa Senhoria, na condição de motorista profissional, vem reiteradamente apresentando falta de urba', 'Advertencia por insubordinação.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (63, 'Advertencia por ir pra casa sem comunicar', 'advertencia', 'Conforme apurado, no dia 14/01/2025, foi constatado que Vossa Senhoria deixou o local de trabalho durante o expediente, sem apresentar qualquer justificativa ou comunicação prévia ao gestor imediata. Tal conduta é considerada inadequada e em desacordo com as normas internas da empresa. Ressaltamos que a ausência não justificada durante o expediente prejudica o andamento das atividades e pode comprometer a eficiência e o bom desempenho da equipe. Com esta advertência, reforçamos a importância de observar as normas e procedimentos internos da empresa, principalmente no que tange à comunicação de eventuais ausências ou saídas do local de trabalho. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando as faltas injustiçadas, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar advertência, pela prática d', 'Conforme apurado, no dia 14/01/2025, foi constatado que Vossa Senhoria deixou o local de trabalho du', 'Advertencia por ir pra casa sem comunicar.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (64, 'Advertencia por jornada e retorno não autorizado', 'advertencia', 'Por meio deste, registramos uma advertência em razão das seguintes ocorrências: No dia 04/12, foi deixada a jornada em aberto até o dia 05/12/2024 sem qualquer justificativa plausível apresentada até o momento. No mesmo período, constatou-se o retorno de viagem do trecho Goiânia-PE para Vitória-PE, realizado sem autorização prévia do gestor responsável, desconsiderando a possibilidade de finalização da jornada no dia 04/12 e cumprimento do intervalo obrigatório de 11 horas de descanso antes do retorno. Essas ações representam o descumprimento das normas internas da empresa e das regulamentações vigentes, comprometendo a segurança e a organização do trabalho. Reiteramos que é indispensável observar as orientações do gestor e respeitar as normas relacionadas à jornada de trabalho e deslocamento, conforme determinado por nossa política interna e pela legislação aplicável. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento d', 'Por meio deste, registramos uma advertência em razão das seguintes ocorrências: No dia 04/12, foi de', 'Advertencia por jornada e retorno não autorizado.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (65, 'Advertencia por marcar a jornada e sair do local', 'advertencia', 'A empresa Transportes Framento, por intermédio de seu representante legal, no exercício regular de seu poder diretivo e disciplinar, com fundamento no artigo 2º da Consolidação das Leis do Trabalho (CLT), vem, por meio desta, advertir formalmente o colaborador Sr. Nélio Marques Alves Correia, pelas condutas praticadas em desacordo com as normas internas da organização. Conforme apurado, nos dias 06 e 09 de setembro de 2025, Vossa Senhoria compareceu às dependências da empresa, realizou o registro de ponto e, em seguida, se retirou da unidade sem prévio aviso ou autorização de seu gestor imediato, conduta esta que caracteriza abandono momentâneo do posto de trabalho e descumprimento das ordens superiores. Tal prática é considerada inadmissível e reprovável, por violar os deveres gerais de conduta do empregado, previstos nos artigos 2º e 3º da CLT, bem como o disposto no artigo 482, alínea “e” e “h” da CLT, que prevê como justa causa para rescisão contratual por dissidia e indisciplina. ', 'A empresa Transportes Framento, por intermédio de seu representante legal, no exercício regular de s', 'Advertencia por marcar a jornada e sair do local.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (66, 'Advertencia por marcar jornada e sair do local', 'advertencia', 'Constatou-se que Vossa Senhoria, na qualidade de motorista profissional desta empresa, em 30/08/2025 procedeu de forma irregular ao registrar o ponto de entrada e, em seguida, ausentar-se do local de trabalho sem autorização, deixando de cumprir suas atividades e responsabilidades previamente estabelecidas. Tal conduta configura falta funcional, pois além de fraudar o controle de jornada, caracteriza descumprimento dos deveres de pontualidade, assiduidade e lealdade contratual, em desrespeito às normas internas da empresa e à legislação trabalhista vigente. Fundamentação Jurídica: Artigo 2º e 3º da CLT – estabelecem a subordinação jurídica e a obrigação do empregado em prestar serviços conforme o contrato. Artigo 58, §1º da CLT – dispõe sobre o registro fidedigno da jornada de trabalho. Artigo 482, alíneas “e” e “h” da CLT – que tratam dissidia e indisciplina como faltas graves. Diante do exposto, esta empresa aplica a presente ADVERTÊNCIA DISCIPLINAR, advertindo-o de que a reincidênci', 'Constatou-se que Vossa Senhoria, na qualidade de motorista profissional desta empresa, em 30/08/2025', 'Advertencia por marcar jornada e sair do local.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (67, 'Advertencia por marcar jornada estando de folga', 'advertencia', 'A empresa Transportes Framento, por meio deste, vem adverti-lo formalmente em razão de conduta inadequada constatada no sistema de apontamento de jornada nos dias 05 e 10/07/2025, datas em que Vossa Senhoria encontrava-se de folga, conforme escala previamente estabelecida pelo seu gesto imediato. Ressaltamos que tal prática configura registro indevido de jornada, comprometendo a veracidade dos dados lançados no controle de ponto da empresa. Diante disso, os registros realizados nesses dias serão desconsiderados e excluídos do controle de jornada, para correção das informações. Informamos que essa conduta fere os princípios da boa-fé contratual (art. 422 do Código Civil), bem como configura infração contratual, nos termos do art. 482, alíneas "e" e "h" da Consolidação das Leis do Trabalho (CLT), que tratam, respectivamente, da dissidia e indisciplina. Esta advertência tem por objetivo orientá-lo para que cesse imediatamente esse tipo de comportamento, sob pena de aplicação de medidas di', 'A empresa Transportes Framento, por meio deste, vem adverti-lo formalmente em razão de conduta inade', 'Advertencia por marcar jornada estando de folga.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (68, 'Advertencia por marcar jornada estando de férias', 'advertencia', 'Considerando que Vossa Senhoria se encontrava formalmente em gozo de férias no período de 09/06/2025 a 08/07/2025, conforme previsto no artigo 129 e seguintes da Consolidação das Leis do Trabalho (CLT), referente ao período aquisitivo de 05/11/2023 a 04/11/2024, foi identificado que, no dia 08/07/2025, durante o referido período de afastamento, Vossa Senhoria acessou o sistema e abriu jornada de trabalho, contrariando a condição de afastamento legal. Tal conduta é considerada inaceitável e inadmissível por esta empresa, por ferir os princípios da organização e controle interno, podendo gerar inconsistências nos registros de jornada e contradições legais, inclusive quanto ao correto cumprimento do descanso remunerado obrigatório previsto no artigo 130 da CLT. Além disso, tal ato pode representar simulação de atividade laboral durante o período de férias, o que contraria o artigo 134 da CLT, que determina que as férias devem ser usufruídas de forma contínua e sem prestação de serviços. S', 'Considerando que Vossa Senhoria se encontrava formalmente em gozo de férias no período de 09/06/2025', 'Advertencia por marcar jornada estando de férias.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (69, 'Advertencia por marcar jornada para colega', 'advertencia', 'Motorista: FELIPE DOS SANTOS PINHEIRO ARANHA Informamos que no dia 13/12/2024, foi constatado que, atendendo ao pedido de seu colega motorista, Hugo Leonardo de Araújo, o senhor deu início à jornada de trabalho utilizando o veículo designado a ele, prática que infringe as políticas internas da empresa. Essa conduta é considerada grave, pois contraria as normas de confiança, responsabilidade e alinhamento às diretrizes estabelecidas pela organização. Lembramos que o cumprimento das políticas internas é essencial para o bom funcionamento da empresa e preservação do ambiente de trabalho. Qualquer reincidência poderá acarretar sanções mais severas, conforme previsto em lei. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os prejuízos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalid', 'Motorista: FELIPE DOS SANTOS PINHEIRO ARANHA Informamos que no dia 13/12/2024, foi constatado que, a', 'Advertencia por marcar jornada para colega.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (70, 'Advertencia por não abastecer o veiculo', 'advertencia', 'Vossa Senhoria, na condição de motorista profissional e responsável pelo veículo de propriedade desta empresa, placa FTA9B84, encontrava-se na base operacional da companhia e, por desatenção e desleixo, deixou de realizar o abastecimento obrigatório do referido veículo. Tal conduta ocasionou transtornos operacionais desnecessários, atrasos nas atividades programadas, além de gerar custo adicional à empresa, prejudicando a eficiência e a regularidade dos serviços prestados. Sua conduta caracteriza descumprimento dos deveres contratuais do empregado, previstos no artigo 2º e 3º da CLT, que estabelecem a subordinação e a obrigação de cumprir corretamente as tarefas determinadas pelo empregador, bem como no artigo 482, alínea “ e” e “h”, da CLT, que tipifica como falta disciplinar dissidia e ato de indisciplina. Ademais, nos termos do artigo 187 do Código Civil, configura-se abuso de direito quando o trabalhador, por ação ou omissão voluntária, excede manifestamente os limites impostos pel', 'Vossa Senhoria, na condição de motorista profissional e responsável pelo veículo de propriedade dest', 'Advertencia por não abastecer o veiculo.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (71, 'Advertencia por não aposntar a jornada', 'advertencia', 'Por meio desta, comunicamos formalmente que foi constatado o descumprimento das políticas internas da Framento Transportes, especificamente no que diz respeito ao registro e à comunicação da jornada de trabalho, conforme estipulado nos regulamentos internos e na legislação vigente. Apesar das orientações prévias realizadas pela equipe de jornada e gestão, verificamos que a conduta inadequada persiste, prejudicando o cumprimento das normas legais e os processos internos da empresa. Destacamos que tal prática infringe: A legislação trabalhista aplicável, como a Lei do Motorista; As diretrizes internas de controle e registro da jornada de trabalho; As orientações previamente recebidas diurnamente. Informamos que o não cumprimento destas normas pode gerar consequências mais severas, conforme previsto na legislação e no regulamento interno da empresa, incluindo medidas disciplinares como suspensão ou rescisão contratual. Solicitamos, portanto, que regularize imediatamente o comportamento, c', 'Por meio desta, comunicamos formalmente que foi constatado o descumprimento das políticas internas d', 'Advertencia por não aposntar a jornada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (72, 'Advertencia por não comparecer ao trabalho', 'advertencia', 'Vossa Senhoria, no dia 09 de julho de 2025, foi convocado expressamente por seu gestor imediato a comparecer à operação do embarcador GPA, a fim de realizar atividade previamente programada e indispensável ao regular funcionamento da operação. Contudo, não compareceu injustificadamente, deixando de cumprir com sua obrigação contratual, o que resultou na perda da diária do veículo, diversos transtornos operacionais à logística da empresa, e ainda exposição negativa da imagem corporativa junto ao embarcador. A ausência injustificada constitui infração disciplinar, nos termos do artigo 482, alínea "e" da Consolidação das Leis do Trabalho (CLT), que autoriza a aplicação de medidas disciplinares em caso de desídia no desempenho das funções. Ademais, o artigo 158, inciso I, da CLT impõe ao empregado a obrigação de cumprir as ordens e instruções do empregador, dentro dos limites legais. Tal conduta também fere os princípios da boa-fé objetiva (art. 422 do Código Civil), e do dever geral de co', 'Vossa Senhoria, no dia 09 de julho de 2025, foi convocado expressamente por seu gestor imediato a co', 'Advertencia por não comparecer ao trabalho.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (73, 'Advertencia por não cumprir a pernoite', 'advertencia', 'Vossa Senhoria, na qualidade de motorista profissional desta empresa, já tendo sido previamente orientado e advertido verbalmente, voltou a descumprir o intervalo mínimo legal de 11 (onze) horas entre duas jornadas de trabalho, conforme constatado nos registros de jornada no dia 25/08/2025.  Ressaltamos que tal conduta é inadmissível, sobretudo em razão da natureza da função exercida, onde o descanso adequado é condição essencial à segurança viária, à integridade física do condutor, de terceiros e à preservação do patrimônio da empresa. O comportamento supramencionado configura descumprimento de norma legal expressa, em violação ao disposto na Lei nº 13.103/2015 (Lei do Motorista), que estabelece o direito ao repouso mínimo de 11 (onze) horas entre jornadas. Referido dispositivo foi recentemente reforçado pela decisão do Supremo Tribunal Federal na ADI 5322, que declarou constitucional essa exigência, consolidando a sua aplicação como instrumento de proteção à saúde do trabalhador e à ', 'Vossa Senhoria, na qualidade de motorista profissional desta empresa, já tendo sido previamente orie', 'Advertencia por não cumprir a pernoite.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (74, 'Advertencia por não cumprir intervalo para alimentação', 'advertencia', 'Vossa Senhoria, colaborador desta empresa, na função de motorista, vem sendo reiteradamente orientado pelo setor de Controle de Jornada e por sua liderança direta quanto à obrigatoriedade de cumprimento dos intervalos legais para refeição e descanso, especialmente o intervalo mínimo de 1 (uma) hora e máximo de 2 (duas) horas, conforme previsto na legislação vigente e nas políticas internas da empresa. Apesar das orientações e advertências verbais anteriores, no dia 07/07/2025,  Vossa Senhoria novamente descumpriu tais determinações, realizando paradas fora do padrão estabelecido ou, por vezes, omitindo completamente as pausas obrigatórias, agindo por vontade própria, em desacordo com as normas legais e internas. No caso específico do transporte rodoviário de cargas, aplica-se a Lei nº 13.103/2015 (Lei do Motorista), que dispõe: Art. 8º. "É assegurado ao motorista profissional, durante a jornada de trabalho, intervalo mínimo de 1 (uma) hora para refeição, podendo coincidir com os interv', 'Vossa Senhoria, colaborador desta empresa, na função de motorista, vem sendo reiteradamente orientad', 'Advertencia por não cumprir intervalo para alimentação.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (75, 'Advertencia por não marcar a jornada corretamente', 'advertencia', 'Através deste documento, informamos que foi constatada a reincidência no descumprimento de normas internas da empresa relacionadas ao registro da jornada de trabalho, onde vários dias no corrente mês não houve o apontamento correto,  Especificamente: Ausência de marcações completas ou corretas da jornada de trabalho, conforme as orientações repassadas pelo gestor e pela equipe responsável pelo controle de jornada. Conforme determina o artigo 74, §2º da Consolidação das Leis do Trabalho (CLT), é dever do empregador manter um registro de controle da jornada dos empregados, sendo, igualmente, dever do empregado realizar as marcações de entrada, saída e intervalos de forma correta e honesta. O não cumprimento dessas obrigações pode acarretar prejuízos à empresa, caracterizando descumprimento contratual por parte do colaborador. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao ', 'Através deste documento, informamos que foi constatada a reincidência no descumprimento de normas in', 'Advertencia por não marcar a jornada corretamente.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (76, 'Advertencia por não marcar a jornada', 'advertencia', 'Por meio desta, vimos formalizar advertência disciplinar escrita, em razão do seguinte fato:  No exercício de suas atividades profissionais, na condição de motorista responsável pelo veículo de propriedade desta empresa, placa BZF0E79, Vossa Senhoria, no dia 04 de julho de 2025, deixou novamente de realizar os devidos apontamentos da jornada de trabalho de forma correta, em desacordo com as normas internas da empresa e a legislação vigente. Ressalte-se que esta não é a primeira ocorrência de conduta semelhante. Vossa Senhoria já foi devidamente orientado em ocasiões anteriores, inclusive advertido verbalmente, quanto à imprescindibilidade do correto preenchimento e registro dos dados referentes à jornada de trabalho. A conduta ora registrada configura descumprimento de obrigação legal, conforme disposto no art. 74, §2º da Consolidação das Leis do Trabalho (CLT), que determina a obrigatoriedade do registro de ponto para controle de jornada. Ademais, a reincidência na prática caracteriza', 'Por meio desta, vimos formalizar advertência disciplinar escrita, em razão do seguinte fato:  No exe', 'Advertencia por não marcar a jornada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (77, 'Advertencia por não pernoitar no embarcador', 'advertencia', 'Na qualidade de motorista profissional desta empresa, Vossa Senhoria descumpriu a determinação expressa de pernoitar no local do embarque, resultando no bloqueio junto ao embarcador. Tal conduta configura descumprimento das obrigações contratuais e das normas internas de operação, infringindo o dever de obediência e de cumprimento das ordens e instruções do empregador, nos termos do art. 2º e do art. 3º da Consolidação das Leis do Trabalho (CLT), bem como o dever de zelo e diligência previsto no art. 482, alínea “e” e “h”, que trata de ato de indisciplina ou insubordinação. Diante do exposto, fica Vossa Senhoria formalmente advertido para que se abstenha de repetir tal conduta, ciente de que reincidências poderão ensejar penalidades mais severas, inclusive as previstas no art. 482 da CLT Salienta-se, ainda, que a presente medida está sendo adotada em observância ao princípio da imediatidade. Solicita-se que Vossa Senhoria assine o presente documento, declarando ciência de seu conteúdo.', 'Na qualidade de motorista profissional desta empresa, Vossa Senhoria descumpriu a determinação expre', 'Advertencia por não pernoitar no embarcador.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (78, 'Advertencia por não realizar o exame toxicológico', 'advertencia', 'Considerando que Vossa Pessoa, na condição de motorista profissional, foi sorteado pelo sistema randômico no dia 03/10/2024, para realização do exame toxicológico, o qual se RECUSOU em fazer, contrariando o que determina a portarias 672 e 612 do MTE, atitude está inaceitável e inadmissível por esta empresa,  cientificamos vossa senhoria que vindo a empresa sofrer multas pela não realização do exame, a empresa poderá repassar para desconto em vossa folha de pagamento.     Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência pela prática do disposto na alínea “e” do Art. 482 da CLT (dissidia).', 'Considerando que Vossa Pessoa, na condição de motorista profissional, foi sorteado pelo sistema rand', 'Advertencia por não realizar o exame toxicológico.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (79, 'Advertencia por não verificar o Frios', 'advertencia', 'Vossa Senhoria, no dia 04 de fevereiro de 2025, durante seu expediente normal, no exercício da função de manobra, não se atentou corretamente ao acionamento do equipamento de frio do veículo de propriedade da empresa, placa FAU1116. Tal descuido resultou na ativação do alarme do equipamento, podendo causar danos à mercadoria do cliente e possíveis prejuízos à empresa Framento. Diante do ocorrido, esta advertência tem o objetivo de alertá-lo sobre a necessidade de maior atenção e cumprimento rigoroso dos procedimentos operacionais da empresa, visando evitar reincidências e garantir a integridade das operações. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alíne', 'Vossa Senhoria, no dia 04 de fevereiro de 2025, durante seu expediente normal, no exercício da funçã', 'Advertencia por não verificar o Frios.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (80, 'Advertencia por pernoite fora do local estabelecido', 'advertencia', 'Vossa Senhoria, na condição de motorista profissional desta empresa, deixou de cumprir determinação expressa da gestão, ao realizar pernoite do veículo de propriedade da empresa em sua residência. Ressalte-se que a orientação vigente, bem como ordem direta do gestor imediato, estabelece que os veículos somente podem pernoitar: Em clientes, quando em situação de aguardo de carga ou descarga; ou No pátio do embarcador BRF, local este que possui cobertura de seguro para eventuais incidentes. Dessa forma, ao descumprir ordem direta de seu superior hierárquico e contrariar normas internas, Vossa Senhoria expôs desnecessariamente o patrimônio da empresa a risco, além de violar regras de conduta que visam à proteção do bem e à segurança operacional. O presente ato disciplinar encontra respaldo: No art. 2º da CLT, que confere ao empregador o poder diretivo para organizar, controlar e disciplinar a atividade laboral; No art. 482, alínea “e” e “h”, da CLT, que trata da dissidia e insubordinação ', 'Vossa Senhoria, na condição de motorista profissional desta empresa, deixou de cumprir determinação ', 'Advertencia por pernoite fora do local estabelecido.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (81, 'Advertencia por retornar a base sem autorização', 'advertencia', 'Vossa Senhoria, na condição de motorista profissional desta empresa, no dia 29/08/2025, encontrava-se em rota de viagem no cliente ATACADÃO e, sem a devida autorização de seu gestor imediato, retornou à base após o horário regulamentar, conduta esta que ocasionou a geração de horas desnecessárias de trabalho e, consequentemente, comprometeu o período mínimo de descanso obrigatório, em desacordo com a Lei nº 13.103/2015 (Lei do Motorista) e com os parâmetros fixados pelo Supremo Tribunal Federal na ADI nº 5322. Tal comportamento caracteriza descumprimento das normas internas da empresa, bem como desatenção às regras de saúde, segurança e jornada de trabalho previstas em lei, infringindo o dever de obediência e disciplina estabelecido no artigo 482, alínea “ e” e “h”, da Consolidação das Leis do Trabalho (CLT). Diante do exposto, e no exercício do poder diretivo e disciplinar conferido pelo artigo 2º da CLT, a empresa aplica a presente ADVERTÊNCIA ESCRITA, advertindo-o(a) de que a reinci', 'Vossa Senhoria, na condição de motorista profissional desta empresa, no dia 29/08/2025, encontrava-s', 'Advertencia por retornar a base sem autorização.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (82, 'Advertencia por solicitar a marcação de ponto para outro colaborador', 'advertencia', 'Motorista: Hugo Leonardo de Araujo Por meio deste documento, empresa Framento inscrita no CNPJ 00.766.315.0002-25, comunica formalmente a Vossa Senhoria que, em 13/12/2024, foi identificado um desvio de conduta que contraria a política interna da empresa. Conforme apurado, vossa senhoria informou que realizaria sessão de fisioterapia nesta data. No entanto, foi constatado que solicitou ao colaborador Felipe dos Santos Pinheiro Aranha que iniciasse a jornada utilizando seu CPF, configurando prática grave e incompatível com os princípios éticos e normativos da organização. Além disso, não foram apresentados atestado ou declaração médica que justificassem a ausência de vossa senhoria na referida data. Tal conduta infringe as normas internas da empresa e prejudica a confiança e o bom funcionamento do ambiente de trabalho. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princí', 'Motorista: Hugo Leonardo de Araujo Por meio deste documento, empresa Framento inscrita no CNPJ 00.76', 'Advertencia por solicitar a marcação de ponto para outro colaborador.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (83, 'Advertencia por transportar produtos', 'advertencia', 'A Framento Transportes vem, por meio desta, aplicar advertência formal em razão de sua conduta inadequada durante a operação de transporte realizada no dia 21/02/2025. Conforme apurado, após o embarque da carga pelo embarcador Seara, o senhor armazenou produtos de consumo próprio no baú do veículo, prática que pode resultar em contaminação cruzada e comprometer a integridade da carga transportada. Tal atitude é considerada inaceitável e inadmissível por esta empresa, pois não apenas infringe normas de segurança e qualidade, mas também expôs negativamente a Framento Transportes perante o cliente. Reforçamos que o não cumprimento das diretrizes da empresa poderá resultar em sanções disciplinares mais severas, incluindo a possibilidade de rescisão contratual, conforme previsto em nosso regulamento interno e na legislação vigente. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ', 'A Framento Transportes vem, por meio desta, aplicar advertência formal em razão de sua conduta inade', 'Advertencia por transportar produtos.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (84, 'Advertencia por uso de celular', 'advertencia', 'Conforme apurado, Vossa Senhoria fez uso de aparelho celular enquanto dirigia o veículo de propriedade desta empresa, placa EEQ8E63, durante atividade de transporte para o embarcador BRF. Em razão desse ato, o referido embarcador, como medida preventiva, incluiu vossa senhoria na “faixa amarela”, advertindo que eventual reincidência poderá resultar em bloqueio de vossa senhoria em definitivo em nível nacional, impedindo-o de realizar transportes para a BRF. Código de Trânsito Brasileiro – CTB (Lei nº 9.503/1997), art. 252, VI: Proíbe dirigir utilizando telefone celular, configurando infração gravíssima, com previsão de multa e pontuação. Consolidação das Leis do Trabalho – CLT (arts. 482 e 158): Estabelece a obrigação do empregado de observar as normas de segurança e disciplina no ambiente de trabalho, sujeitando-o a medidas disciplinares em caso de descumprimento. Normas Internas de Segurança e Política de Uso de Veículos da Empresa: O uso de celular ao volante compromete a integridad', 'Conforme apurado, Vossa Senhoria fez uso de aparelho celular enquanto dirigia o veículo de proprieda', 'Advertencia por uso de celular.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (85, 'Advertencia por uso de jornada longa', 'advertencia', 'A empresa Transportes Framento, na qualidade de empregadora, com fundamento em seu poder diretivo previsto no art. 2º da CLT, aplica por meio desta advertência disciplinar ao colaborador acima identificado, em razão de conduta incompatível com as normas legais e internas relativas à jornada de trabalho, segurança e saúde. Conforme dados do sistema de jornada e telemetria, e apesar de orientações e advertências verbais anteriores, constatou-se que Vossa Senhoria manteve jornada aberta de 25/07/2025 às 19h11 até 27/07/2025 às 02h50, totalizando mais de 30 horas consecutivas de jornada, em desacordo com os limites legais estabelecidos pela Lei nº 13.103/2015 (Lei do Motorista). Além disso, foi identificada a realização de viagem de aproximadamente 400 km após o término das atividades na doca, sem o descanso mínimo de 11 horas, exigido pelo art. 235-C, §3º, da referida Lei, o que compromete a segurança e viola normas constitucionais de proteção à saúde (CF, art. 7º, XXII), bem como a juris', 'A empresa Transportes Framento, na qualidade de empregadora, com fundamento em seu poder diretivo pr', 'Advertencia por uso de jornada longa.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (86, 'Advertencia por uso incorreto do cinto de segurança', 'advertencia', 'Por meio desta, a empresa Transportes Framento, vem formalmente adverti-lo pelo descumprimento das normas de segurança ao não utilizar corretamente o cinto de segurança enquanto conduzia veículo de propriedade da empresa, fato ocorrido em (DATA) conforme registrado e comprovado por meio das imagens (fotos)  O uso do cinto de segurança é obrigatório conforme previsto no Código de Trânsito Brasileiro (CTB), especialmente no artigo 65, que estabelece: "É obrigatório o uso do cinto de segurança para condutor e passageiros em todas as vias do território nacional, salvo em situações regulamentadas pelo CONTRAN." Além disso, tal conduta infringe normas internas de segurança da empresa e configura ato faltoso passível de sanção disciplinar conforme o artigo 482, alínea "h" da Consolidação das Leis do Trabalho (CLT), que prevê a possibilidade de punição em caso de ato de indisciplina ou insubordinação. A Transportes Framento reforça que a segurança dos colaboradores e o cumprimento da legislaçã', 'Por meio desta, a empresa Transportes Framento, vem formalmente adverti-lo pelo descumprimento das n', 'Advertencia por uso incorreto do cinto de segurança.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (87, 'Advertencia por uso indevido do celular da empresa', 'advertencia', 'Por meio deste documento, informamos que foi identificado, no dia 14 de novembro de 2024, o uso inadequado do smartphone corporativo disponibilizado pela empresa, em desacordo com as normas internas de conduta. Especificamente, constatou-se o acesso a sites de conteúdo inadequado, o que resultou no consumo excessivo de banda e comprometeu o pacote de dados disponibilizado para as operações e atividades corporativas. Ressaltamos que o uso dos equipamentos fornecidos pela empresa deve seguir estritamente as diretrizes estabelecidas em nossas políticas internas, sendo reservado exclusivamente para finalidades profissionais Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando as faltas injustiçadas, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “', 'Por meio deste documento, informamos que foi identificado, no dia 14 de novembro de 2024, o uso inad', 'Advertencia por uso indevido do celular da empresa.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (88, 'Advertencia', 'advertencia', 'Vossa Senhoria, na qualidade de motorista profissional, responsável pelo veículo de placa BYZ-6076, de propriedade da empresa Transportes Framento, descumpriu ordem direta do gestor da operação, ao sair antecipadamente para realizar o embarque com escolta na unidade da JBS, no Rio de Janeiro, sem a devida autorização e em desacordo com o planejamento operacional previamente estabelecido. Tal conduta resultou na suspensão de Vossa Senhoria das operações pela empresa embarcadora JBS, em razão do descumprimento das regras estabelecidas no Plano de Gerenciamento de Risco (PGR). A liberação para retorno às atividades com a referida embarcadora ficará condicionada à apresentação do certificado de conclusão do curso “Conecta JBS”, conforme exigência da contratante. Essa prática é considerada grave e inadmissível por esta empresa, pois compromete a segurança operacional, viola os protocolos de segurança acordados com os clientes e infringe normas internas de conduta profissional. Fundamentação', 'Vossa Senhoria, na qualidade de motorista profissional, responsável pelo veículo de placa BYZ-6076, ', 'Advertencia.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (89, 'Advertencias por apontamento de jornadas', 'advertencia', 'THIAGO VIANA A empresa TRANSPORTES FRAMENTO LTDA, na qualidade de empregadora e no exercício regular de seu poder diretivo e disciplinar, previsto no artigo 2º da Consolidação das Leis do Trabalho (CLT), vem, por meio desta, aplicar ADVERTÊNCIA DISCIPLINAR ao empregado THIAGO VIANA, em razão da seguinte conduta: Conforme apurado, em 30/08/2025, Vossa Senhoria, na condição de motorista profissional, enviou jornada com o CPF do condutor Cristiano de Jesus Gomes, a pedido deste último, prática absolutamente inaceitável e inadmissível, que resultou no registro de jornada indevida vinculada ao veículo de placa BZF8408. Tal conduta caracteriza descumprimento de normas internas da empresa, além de violar o dever de probidade e boa-fé contratual (artigo  3º da CLT, combinado com o artigo 422 do Código Civil aplicado subsidiariamente), bem como afronta o poder diretivo e disciplinar do empregador (artigo 2º da CLT). Ademais, ressalta-se que o comportamento adotado expõe a empresa a riscos de or', 'THIAGO VIANA A empresa TRANSPORTES FRAMENTO LTDA, na qualidade de empregadora e no exercício regular', 'Advertencias por apontamento de jornadas.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (90, 'Advertencias por falta injustificada', 'advertencia', 'Através do presente documento, vimos aplicar-lhe advertência disciplinar, em razão da seguinte conduta: No dia 07 de julho de 2025, Vossa Senhoria, na condição de motorista profissional, faltou ao trabalho injustificadamente, sem apresentar qualquer justificativa válida para a ausência. Tal conduta comprometeu seriamente a operação logística, causando transtornos operacionais, além de expor negativamente a imagem da empresa frente ao embarcador envolvido na operação. A ausência injustificada ao trabalho configura ato de indisciplina e desídia, nos termos do art. 482, alínea "e" e "h", da Consolidação das Leis do Trabalho (CLT). Além disso, a conduta infringe o princípio da boa-fé contratual previsto no art. 422 do Código Civil, e viola deveres funcionais descritos no art. 2º da Lei nº 13.103/2015 (Lei do Motorista), que exige conduta compatível com a segurança e responsabilidade nas atividades de transporte. Informamos que este tipo de comportamento poderá acarretar sanções mais severa', 'Através do presente documento, vimos aplicar-lhe advertência disciplinar, em razão da seguinte condu', 'Advertencias por falta injustificada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (91, 'Advetencia por não usar o cinto', 'advertencia', 'A Transportes Framento, no exercício regular de seu poder diretivo e disciplinar, com fundamento no artigo 2º da Consolidação das Leis do Trabalho (CLT), ADVERTE FORMALMENTE Vossa Senhoria pela conduta constatada nos dias 12, 13 e 14 de setembro de 2025, quando, na função de motorista profissional, deixou de utilizar o cinto de segurança durante a jornada de trabalho. O uso do cinto de segurança é obrigatório, conforme previsto: Art. 167 do Código de Trânsito Brasileiro (Lei nº 9.503/1997), que impõe a utilização do cinto de segurança por condutores e passageiros; Política Interna de Segurança e Saúde no Trabalho da empresa, amplamente divulgada e de conhecimento de todos os colaboradores. A conduta verificada expõe o empregado a risco grave à integridade física, além de gerar passivos trabalhistas e cíveis para a empregadora, afrontando o dever de observar as normas de segurança e medicina do trabalho (art. 158, I e II, da CLT). Fica registrado que a reincidência poderá ensejar sançõe', 'A Transportes Framento, no exercício regular de seu poder diretivo e disciplinar, com fundamento no ', 'Advetencia por não usar o cinto.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (92, 'Advretencia consulta', 'advertencia', 'Constatamos que, no dia 17/03/2025, você se ausentou do trabalho para comparecer a uma consulta previamente agendada sem comunicar previamente a empresa, descumprindo assim as normas internas de comunicação de ausências. Lembramos que a comunicação prévia de ausências é essencial para o bom funcionamento da equipe e a organização das atividades. Dessa forma, reforçamos a necessidade de seguir os procedimentos internos para solicitar e justificar eventuais ausências. Diante do exposto, esta advertência tem caráter disciplinar e visa reforçar a importância do cumprimento das regras da empresa. O não cumprimento poderá acarretar novas medidas disciplinares, conforme previsto no regulamento interno e na legislação vigente.', 'Constatamos que, no dia 17/03/2025, você se ausentou do trabalho para comparecer a uma consulta prev', 'Advretencia consulta.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (93, 'Advretencia por desobediência', 'advertencia', 'Por meio desta, registramos formalmente uma advertência em razão de sua conduta no desempenho de suas funções. Conforme apurado, no dia 28/02/2025, Vossa Senhoria recusou-se a pernoitar na cidade de Capinza/SC para concluir as entregas no sábado, 01/03/2025, optando por um deslocamento desnecessário que gerou custos adicionais à empresa. No sábado, diante da necessidade de concluir as entregas, a empresa precisou enviar outro motorista para substituí-lo, porém, o mercado destinatário recusou-se a receber a mercadoria, resultando em prejuízos operacionais. Além disso, no dia 03/03/2025, após nova solicitação do gestor para que comparecesse ao embarcador BRF a fim de realizar a devolução da mercadoria, Vossa Senhoria recusou-se novamente, alegando compromissos particulares. Diante do exposto, sua atitude configura descumprimento das diretrizes e responsabilidades inerentes ao seu cargo, prejudicando o fluxo de trabalho e ocasionando transtornos à empresa. Sendo assim, esta advertência te', 'Por meio desta, registramos formalmente uma advertência em razão de sua conduta no desempenho de sua', 'Advretencia por desobediência.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (94, 'Advretencia por não fazer o canhato digital', 'advertencia', 'Por meio desta, notificamos que, em 18/02/2025, foi identificado que vossa senhoria deixou de realizar os procedimentos de canhoto digital, conforme foi devidamente instruído. Tal procedimento é uma norma da empresa Framento Transportes e deve ser cumprido rigorosamente. O não cumprimento desta norma compromete o controle interno e a eficiência operacional da empresa, podendo gerar impactos nos processos administrativos. Dessa forma, esta advertência tem caráter disciplinar e visa alertá-lo(a) sobre a necessidade de seguir corretamente os procedimentos estabelecidos. Solicitamos que redobre a atenção quanto ao cumprimento das diretrizes da empresa. O não cumprimento das normas poderá resultar em medidas disciplinares mais severas, conforme previsto no regulamento interno Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os r', 'Por meio desta, notificamos que, em 18/02/2025, foi identificado que vossa senhoria deixou de realiz', 'Advretencia por não fazer o canhato digital.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (95, 'Asvertencia por não abastecer', 'advertencia', 'Conforme apurado, no dia 12 de abril de 2025, vossa senhoria deixou de reabastecer o tanque de combustível do veículo sob sua responsabilidade, de placa (      ) , o qual alimenta o termo king utilizado para preservação das mercadorias transportadas. Essa omissão resultou na pane seca do aparelho, que parou de funcionar durante o transporte, gerando risco significativo de perda das mercadorias e prejuízos para a empresa. Reforçamos que é de responsabilidade do condutor realizar a devida verificação e manutenção preventiva do veículo, incluindo o abastecimento de combustível. Esse procedimento é fundamental para garantir a eficiência operacional e evitar situações como a mencionada. Desta forma, estamos emitindo esta advertência formal para registrar o ocorrido e alertá-la quanto à necessidade de maior atenção e cumprimento das suas responsabilidades no futuro. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos ', 'Conforme apurado, no dia 12 de abril de 2025, vossa senhoria deixou de reabastecer o tanque de combu', 'Asvertencia por não abastecer.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (96, 'Suspensao por desvio de rota', 'suspensao', 'A empresa Transportes Framento, por meio de seu representante legal, no exercício regular do poder diretivo e disciplinar que lhe confere o artigo 2º da Consolidação das Leis do Trabalho (CLT), bem como em conformidade com o dever de obediência às normas internas previsto no artigo 482, alínea “e” e “h” da CLT, vem por meio do presente aplicar a penalidade de SUSPENSÃO DISCIPLINAR a Vossa Senhoria, na qualidade de motorista profissional desta empresa, pelos fatos a seguir expostos. Conforme apurado, no dia 25/07/2025, Vossa Senhoria, após a realização de entrega no cliente Sendas, deixou de retornar ao destino estabelecido (Visa) e, sem qualquer justificativa ou autorização de seu gestor imediato, deslocou-se para o interior de Maceió/AL, ocasionando desvio de rota não autorizado. Tal conduta gerou transtornos operacionais à empresa, além de ocasionar consumo desnecessário de óleo diesel, impactando diretamente os custos da operação. Registra-se que, em observância ao princípio da imed', 'A empresa Transportes Framento, por meio de seu representante legal, no exercício regular do poder d', 'Suspensao por desvio de rota.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (97, 'Suspensão - por bater o veiculo numa árvore', 'suspensao', 'Por meio deste, registramos a ocorrência envolvendo o veículo da empresa, de placa LTA9613, sob sua responsabilidade operacional. No dia 04/12/2024, foi constatado que o referido veículo sofreu danos na carroceria após colidir com uma copa de árvore, resultando em gastos inesperados para reparos e transtornos operacionais à rotina da empresa. Após análise preliminar, verificou-se que a colisão ocorreu devido à desatenção durante a condução do veículo. Ressaltamos que a condução segura e atenta é indispensável para preservar o patrimônio da empresa, além de garantir a segurança de todos os envolvidos. Reiteramos a importância de cumprir com as normas da empresa e de adotar as devidas precauções na condução de suas responsabilidades, especialmente no uso de veículos da frota. Solicitamos maior atenção em suas atividades futuras, para evitar a repetição de situações como a relatada. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para a', 'Por meio deste, registramos a ocorrência envolvendo o veículo da empresa, de placa LTA9613, sob sua ', 'Suspensão - por bater o veiculo numa árvore.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (98, 'Suspensão deslocamento', 'suspensao', 'No exercício de suas funções, Vossa Senhoria, na condição de motorista profissional, no dia 15 de junho de 2025, deslocou-se com o veículo de propriedade da empresa, placa TTD4J46, do Município de Promissão – SP até sua residência em Marília – SP, e retornou no dia seguinte, 16 de junho de 2025, para Promissão – SP, sem a devida autorização do gestor imediato. Tal conduta resultou em um deslocamento indevido de 184 km, ocasionando desperdício de combustível, desvio de finalidade do veículo e risco à gestão das diárias contratuais do veículo dedicado a serviço da empresa. Infrações Cometidas A conduta caracteriza: Desobediência às ordens superiores, nos termos do artigo 482, alínea " E e H" da CLT, que prevê a possibilidade de rescisão do contrato de trabalho por ato de dissidia e indisciplina.  Uso indevido de patrimônio da empresa, infringindo o dever de boa-fé e lealdade previsto no artigo 422 do Código Civil; Prejuízo potencial à operação logística contratual, afetando a imagem e o ', 'No exercício de suas funções, Vossa Senhoria, na condição de motorista profissional, no dia 15 de ju', 'Suspensão deslocamento.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (99, 'Suspensão em rota diferente', 'suspensao', 'A empresa Transportes Framento Ltda., na qualidade de empregadora e no exercício regular de seu poder diretivo e disciplinar, conforme previsto no art. 2º da Consolidação das Leis do Trabalho (CLT), vem, por meio desta, aplicar suspensão disciplinar de 03 (três) dias, iniciando em xx/xx/xxxx finalizando em xx/xx/xxxx em razão de conduta incompatível com as normas internas da empresa e com a legislação vigente. Conforme apurado, no dia 23/10, o colaborador abriu a jornada de trabalho registrada, porém não deu prosseguimento ao carregamento do veículo. Além disso, no dia 18/10, seguiu viagem por rota não autorizada, divergente da previamente determinada pela empresa. Durante o percurso fora da rota estabelecida, deixou de atender às ligações da gestão, sendo necessária a intervenção da Escolta da Raster até a localização da carreta. Tais condutas, consistentes em descumprimento das normas internas, falta de comunicação com o gestor e omissão de justificativas, configuram ato de indiscipl', 'A empresa Transportes Framento Ltda., na qualidade de empregadora e no exercício regular de seu pode', 'Suspensão em rota diferente.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (100, 'Suspensão por abandonar o caminhão Kit BRF', 'suspensao', 'Por meio desta, comunicamos que, em 21/01/2025, durante o turno em que o senhor estava escalado para acompanhar a entrega de kits da BRF, foi constatada sua ausência injustificada no local de trabalho, sem qualquer comunicação prévia ou posterior aos gestores responsáveis. Além disso, foi identificado que: O veículo utilizado para a operação foi abandonado no local sem supervisão que era de vossa responsabilidade; A porta do baú do veículo permaneceu aberta, comprometendo a temperatura dos produtos. Os funcionários da BRF foram obrigados a retirar seus kits sem o devido acompanhamento e supervisão. Essas ações configuram descumprimento grave das normas de conduta e das obrigações previstas no contrato de trabalho, além de colocar em risco a qualidade dos produtos e a reputação da empresa perante o cliente. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imedi', 'Por meio desta, comunicamos que, em 21/01/2025, durante o turno em que o senhor estava escalado para', 'Suspensão por abandonar o caminhão Kit BRF.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (101, 'Suspensão por abrir jornada e ir pra casa', 'suspensao', 'Após análise e apuração dos fatos ocorridos no dia 18/01/2024, foi constatado que Vossa Senhoria compareceu às dependências da empresa, registrou o início de sua jornada de trabalho e, em seguida, ausentou-se do local sem qualquer justificativa ou comunicação prévia aos gestores responsáveis. Esse comportamento caracteriza descumprimento de normas internas da empresa, especialmente as relacionadas ao controle da jornada de trabalho e à transparência na comunicação com a gestão. Tais condutas comprometem a operação e a produtividade da equipe, além de violarem os princípios de disciplina e responsabilidade profissional esperados de todos os colaboradores, além de gerar inúmeros transtornos operacionais, uma vez que a Framento tem agenda de entregas a ser cumpridas com o embarcador.  Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Consid', 'Após análise e apuração dos fatos ocorridos no dia 18/01/2024, foi constatado que Vossa Senhoria com', 'Suspensão por abrir jornada e ir pra casa.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (102, 'Suspensão por bater o veiculo da empresa', 'suspensao', 'Com base nos registros internos e no Boletim de Ocorrência número 2024 1207 4107 093, comunicamos que foi constatado um incidente envolvendo o veículo da empresa, de placa FWP9G57, sob sua responsabilidade, no dia 07/12/2024 durante manobra no pátio do embarcador, por descuido/desatenção vossa senhoria colidiu com outro veículo de placa LTA6583 também de propriedade da empresa, que se encontrava parado e estacionado. O incidente resultou em danos materiais em ambos os veículos. Reiteramos que, considerando o espaço adequado para manobras no local, o ocorrido caracteriza falta de atenção e zelo pelo patrimônio da empresa. Tal conduta está em desacordo com os princípios de responsabilidade e cuidado exigidos de nossos colaboradores. Reiteramos a importância de cumprir com as normas da empresa e de adotar as devidas precauções na condução de suas responsabilidades, especialmente no uso de veículos da frota. Solicitamos maior atenção em suas atividades futuras, para evitar a repetição de s', 'Com base nos registros internos e no Boletim de Ocorrência número 2024 1207 4107 093, comunicamos qu', 'Suspensão por bater o veiculo da empresa.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (103, 'Suspensão por deslocar com o veiculo para sua residencia sem atorizaçaõ', 'suspensao', 'Após averiguações internas, foi constatado que no dia 23 de outubro de 2024, o senhor se deslocou do Rio de Janeiro (RJ) para Itupeva (SP) com o veículo da empresa placa (SRU6J07), sem a devida autorização prévia do seu gestor gerando prejuízos e custos para empresa. Este comportamento constitui uma violação das normas internas da empresa, especificamente no que tange ao uso de veículos e deslocamentos não autorizados, conforme política interna da empresa Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os prejuízos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de suspensão sem remuneração por 3 dias, pela prática do disposto na alínea “h” do Art. 482 da CLT (indisciplina e insubordinação).', 'Após averiguações internas, foi constatado que no dia 23 de outubro de 2024, o senhor se deslocou do', 'Suspensão por deslocar com o veiculo para sua residencia sem atorizaçaõ.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (104, 'Suspensão por dissidia', 'suspensao', 'Por meio deste, a empresa Framento Transporte, comunica que, após análise do ocorrido no dia 16/12/2024 foi identificada uma atitude que infringiu as normas e políticas internas da empresa, conforme descrito a seguir: No dia mencionado, Vossa Senhoria recusou realizar uma viagem previamente programada com destino ao Rio de Janeiro, resultando em um impacto negativo nas operações e no cumprimento dos compromissos firmados pela empresa com clientes e parceiros. A recusa em cumprir o itinerário previamente configuram condutas incompatíveis com os padrões de profissionalismo e comprometimento esperados dos colaboradores. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os prejuízos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de suspensão de 5 dias sem salário e D', 'Por meio deste, a empresa Framento Transporte, comunica que, após análise do ocorrido no dia 16/12/2', 'Suspensão por dissidia.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (105, 'Suspensão por estar com CNH vencida', 'suspensao', 'Vossa senhoria, na condição de motorista profissional, tem a obrigação de manter sua Carteira Nacional de Habilitação (CNH) válida e dentro do prazo de vigência, conforme exige a legislação vigente e as normas internas da empresa. No entanto, foi identificado que sua CNH se encontra vencida, o que o impossibilita de exercer suas funções legalmente. Além disso, no dia 07 de abril de 2025, foi constatada divergência entre o horário registrado por vossa senhoria, uma vez que registrou manualmente o início da atividade as 06h30 e o horário efetivamente registrado no sistema de acesso da embarcador BRF 08h57, o que sugere que vossa senhoria marcou o início de vossa jornada antecipada, prática que constitui falta grave, passível de penalidades conforme as normas internas e a Consolidação das Leis do Trabalho (CLT). Solicitamos que, durante o período de suspensão, vossa senhoria se abstenha de comparecer às dependências da empresa, salvo se convocado formalmente. Considerando também, que este', 'Vossa senhoria, na condição de motorista profissional, tem a obrigação de manter sua Carteira Nacion', 'Suspensão por estar com CNH vencida.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (106, 'Suspensão por excesso de velocidade', 'suspensao', 'Após a verificação dos registros de monitoramento e controle de velocidade dos veículos da empresa, constatamos que no dia 08/07/2025, enquanto conduzia o veículo placa FWY0I97 Vossa Senhoria excedeu os limites de velocidade, chegando a 84km/h sendo que lime máximo permitido em lei e pela política da empresa é de no máximo 80km/h.  Conforme as normas de segurança estabelecidas pela empresa Framento é expressamente proibido exceder os limites de velocidade, especialmente durante condições climáticas adversas, como chuva, que aumentam os riscos de acidentes. Esse tipo de comportamento coloca em risco não apenas a sua segurança, mas também a de terceiros, bem como a integridade do patrimônio da empresa e de terceiros. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pes', 'Após a verificação dos registros de monitoramento e controle de velocidade dos veículos da empresa, ', 'Suspensão por excesso de velocidade.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (107, 'Suspensão por extravio de mercadoria', 'suspensao', 'Considerando que Vossa Pessoa, na condição de motorista profissional, apresentou comportamento inadequado, por nos dias 26 a 31/08/2024, ter ocorrido a ocorrência de extraviado mercadorias do veículo (Placa LTA-9613), gerando prejuízos para a empresa, atitude está inaceitável e inadmissível por esta empresa.  Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar suspensão por 3 dias sem remuneração e DSR, pela prática do disposto na alínea “E” do Art. 482 da CLT (dissidia).', 'Considerando que Vossa Pessoa, na condição de motorista profissional, apresentou comportamento inade', 'Suspensão por extravio de mercadoria.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (108, 'Suspensão por falta ao trabalho e uniforme', 'suspensao', 'Considerando que nos dias 01 e 03 de março de 2025, Vossa Senhoria não compareceu ao trabalho sem apresentar justificativa formal e, ao ser questionado pelo gestor sobre as referidas ausências, respondeu de maneira irônica: "Não vim trabalhar porque não quis", tal conduta caracteriza descumprimento das normas internas da empresa, impactando negativamente a organização. Além disso, no dia 05 de março de 2025, ao se apresentar para o expediente, Vossa Senhoria estava sem o uniforme obrigatório exigido pelo embarcador BRF, impossibilitando-o de exercer suas atividades laborais e gerando transtornos operacionais, além de comprometer a imagem da empresa perante o embarcador. Diante da reincidência de condutas inadequadas e em conformidade com as normas internas da empresa, comunicamos a aplicação de 5 (cindo) dias de suspensão, a contar de, como medida disciplinar. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos ', 'Considerando que nos dias 01 e 03 de março de 2025, Vossa Senhoria não compareceu ao trabalho sem ap', 'Suspensão por falta ao trabalho e uniforme.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (109, 'Suspensão por falta ao trabalho', 'suspensao', 'Considerando que nos dias 04/12/2024 e 05/12/2024 Vossa Senhoria chegou atrasado ao trabalho, mesmo após ter sido advertido verbalmente em ocasiões anteriores, comunicamos a aplicação de suspensão disciplinar, conforme previsto nas normas internas da empresa e na legislação vigente. Os atrasos reiterados causaram prejuízos à operação e transtornos ao bom andamento das atividades no setor, comprometendo o desempenho da equipe e os objetivos da organização. Tal comportamento contraria as disposições previstas no Regulamento Interno da Empresa, em especial as normas relativas à pontualidade e comprometimento no exercício das funções. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando as faltas injustiçadas, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de suspensão de 5 dia sem remuneração e D', 'Considerando que nos dias 04/12/2024 e 05/12/2024 Vossa Senhoria chegou atrasado ao trabalho, mesmo ', 'Suspensão por falta ao trabalho.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (110, 'Suspensão por falta de calço', 'suspensao', 'Vossa Senhoria, na função de manobrista, deixou de cumprir as normas de segurança estabelecidas pela empresa Transportes Framento e pelo embarcador BRF, ao não utilizar os calços de segurança nos veículos sob sua responsabilidade, medida obrigatória para prevenção de acidentes nas áreas operacionais. Tal conduta configura negligência grave quanto às normas internas de segurança do trabalho, colocando em risco a integridade física de pessoas, veículos e instalações. Em razão dessa infração, a empresa BRF procedeu com o bloqueio de seu acesso às dependências por 1 (um) dia, impedindo o regular desempenho de suas funções. Diante do exposto, e com base no art. 482, alínea “b”, da Consolidação das Leis do Trabalho (CLT), que dispõe sobre as penalidades aplicáveis ao empregado por ato de negligência, e considerando os princípios da gradação das penas e da proporcionalidade, comunicamos que será aplicada a penalidade disciplinar de: Suspensão de 1 (um) dia a contar de 30/05/2025 sem remuneraç', 'Vossa Senhoria, na função de manobrista, deixou de cumprir as normas de segurança estabelecidas pela', 'Suspensão por falta de calço.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (111, 'Suspensão por falta de urbanidade', 'suspensao', 'Considerando o ocorrido em 15/09/2025, quando Vossa Senhoria dirigiu-se de forma desrespeitosa a colega de trabalho, conduta que infringe as normas internas de convivência e o dever de urbanidade no ambiente laboral, fica aplicada a penalidade de SUSPENSÃO DISCIPLINAR de 01 (um) dia, com início em 22/09/2025 e término em 23/09/2025, data em que deverá retomar suas atividades normalmente. A medida encontra amparo no art. 482, alínea “h”, da Consolidação das Leis do Trabalho (CLT), que prevê sanções em casos de ato de indisciplina, bem como no art. 482, alínea “k”, da CLT, que abrange ato lesivo da honra ou da boa fama praticado contra qualquer pessoa no ambiente de trabalho. Baseia-se também no poder disciplinar do empregador, decorrente do art. 2º da CLT, além de normas internas desta empresa. Ressaltamos que a reincidência poderá ensejar aplicação de penalidades mais severas, inclusive rescisão contratual por justa causa. Salienta-se, ainda, que esta medida está sendo adotada em conso', 'Considerando o ocorrido em 15/09/2025, quando Vossa Senhoria dirigiu-se de forma desrespeitosa a col', 'Suspensão por falta de urbanidade.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (112, 'Suspensão por falta injustificada', 'suspensao', 'Este comunicado tem o objetivo de formalizar a suspensão disciplinar decorrente de inúmeras faltas injustificadas ocorridas nos dia 04/11/2024, até 11/11/2027, na qual sua ausência causou a indisponibilidade da cavalo/carreta conjunto de placas BZB8391, PRR8186. Este fato gerou perda da diária da careta e desconforto com o cliente FRIMESA, ocasionando prejuízos tanto financeiros quanto de relacionamento para a empresa.  De acordo com as normas internas e o contrato de trabalho, é necessário que todos os colaboradores compareçam ao seu posto de trabalho ou apresentem justificativa formal caso precisem se ausentar. Informamos que a ausência injustificada constitui falta disciplinar, de acordo com as normas da empresa e a legislação trabalhista aplicável Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando as faltas injustiçadas, ', 'Este comunicado tem o objetivo de formalizar a suspensão disciplinar decorrente de inúmeras faltas i', 'Suspensão por falta injustificada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (113, 'Suspensão por falta', 'suspensao', 'Em 11 de setembro de 2025, o empregado faltou ao trabalho sem qualquer justificativa prévia ou posterior, ocasionando severo comprometimento das atividades operacionais e logísticas da empresa. A ausência injustificada: Interrompeu o regular andamento das entregas, obrigando a empresa a contratar, em caráter emergencial, profissional de terceiros para suprir a demanda; Gerou impacto financeiro e operacional decorrente da necessidade de contratação extraordinária; Expos negativamente a imagem da empresa perante o embarcador, afetando a confiança comercial e a credibilidade institucional. Tais condutas configuram violação dos deveres de assiduidade, pontualidade, diligência e boa-fé objetiva, previstos implicitamente no contrato de trabalho e no art. 2º e 3º da CLT, que impõem ao empregado a obrigação de prestação de serviços com regularidade e observância das ordens e necessidades da atividade empresarial. Art. 482, alínea “e” e “h””, da Consolidação das Leis do Trabalho (CLT): estabele', 'Em 11 de setembro de 2025, o empregado faltou ao trabalho sem qualquer justificativa prévia ou poste', 'Suspensão por falta.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (114, 'Suspensão por insubordinação', 'suspensao', 'Comunicamos que, após análise dos fatos ocorridos nos dias 26/01/2025 e 27/01/2025, foram constatadas as seguintes condutas que configuram infrações às normas internas da empresa: No dia 26/01/2025, vossa senhoria concedeu carona em veículo da empresa, prática está proibida conforme as políticas internas, amplamente divulgadas e de ciência de todos os colaboradores. No dia 27/01/2025, houve a recusa em desempenhar as atividades determinadas pelo Gestor, caracterizando desobediência às orientações superiores, gerando inúmeros transtornos operacionais no embarcador. Tais comportamentos configuram descumprimento das normas estabelecidas pela empresa e comprometem o bom funcionamento e a disciplina no ambiente de trabalho. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa', 'Comunicamos que, após análise dos fatos ocorridos nos dias 26/01/2025 e 27/01/2025, foram constatada', 'Suspensão por insubordinação.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (115, 'Suspensão por não cumprir as determinações', 'suspensao', 'Considerando suas funções como motorista profissional, responsável pelo veículo de propriedade da empresa, placa EXS4681, constatamos o descumprimento das diretrizes operacionais estabelecidas pelo gestor, resultando em prejuízos e transtornos operacionais, conforme relatado abaixo: No dia 22/03/2025, o senhor descumpriu a solicitação para chegar ao Terminal de Suprimentos e Produção (TSP) operação BRF Salvador de Seabra para descarregar a carreta, tendo interrompido a viagem sem aviso prévio aos responsáveis. No dia 23/03/2025, o senhor não retornou ao Centro de Distribuição (CD) BRF Salvador para realizar o novo carregamento conforme a programação estabelecida. Tais condutas resultaram em prejuízos operacionais, perda de agenda e impactos negativos na imagem da empresa perante o cliente, configurando descumprimento de ordens superiores e violação das normas internas da empresa. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para a', 'Considerando suas funções como motorista profissional, responsável pelo veículo de propriedade da em', 'Suspensão por não cumprir as determinações.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (116, 'Suspensão por não informar problema no termo king', 'suspensao', 'Na condição de motorista profissional, responsável pelo veiculo de propriedade da empresa placa FZB8H26, no dia 02/03/2025, vossa senhoria identificou que o equipamento Thermo King, responsável pela refrigeração da câmara fria do veículo, apresentou problemas. No entanto, Vossa Senhoria não comunicou a manutenção para providenciar o devido conserto, conforme previsto nos procedimentos internos da empresa. Além disso, ao manter o equipamento ligado e não realizar a checagem necessária – obrigação que é de sua exclusiva responsabilidade –, colocou em risco a integridade dos produtos do embarcador BRF, podendo gerar prejuízos à empresa Framento em ressarcir as perdas de mercadoria além de denegrir negativamente a imagem da empresa. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientific', 'Na condição de motorista profissional, responsável pelo veiculo de propriedade da empresa placa FZB8', 'Suspensão por não informar problema no termo king.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (117, 'Suspensão por não participar de treinamento obrigatório', 'suspensao', 'Considerando que Vossa Senhoria não participou do treinamento obrigatório disponibilizado pelo embarcador BRF, realizado durante o expediente de trabalho, informamos que tal ausência resultou no bloqueio junto ao referido embarcador. A não realização do treinamento compromete diretamente as operações da empresa, gerando transtornos operacionais e impactando o fluxo de atividades. Diante disso, comunicamos a aplicação de 3 (três) dias de suspensão disciplinar, conforme as diretrizes internas e normativas aplicáveis. Reforçamos a importância do cumprimento das obrigações e orientações estabelecidas para evitar futuras ocorrências.  Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando as faltas injustiçadas, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de suspensão, sem salário e DSR pelos dias', 'Considerando que Vossa Senhoria não participou do treinamento obrigatório disponibilizado pelo embar', 'Suspensão por não participar de treinamento obrigatório.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (118, 'Suspensão por não usar sinto de segurança', 'suspensao', 'Considerando que Vossa Pessoa, na condição de motorista profissional, no dia 18/06/2024, estava conduzindo o veículo (placa EGT4E81) sem sinto de segurança, o que implicou o bloqueio de vossa senhoria pela BRF por 15 dias.  Considerando que, o comportamento de Vossa Senhoria foi um ato inseguro, sendo que não cumpriu a legislação de transito, não cumpriu as políticas da empresa o que justifica a presente advertência.  Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando as transgressões cometida, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de suspensão de três dias, sem remuneração e DSR, pela prática do disposto na alínea “h” do Art. 482 da CLT (Insubordinação)', 'Considerando que Vossa Pessoa, na condição de motorista profissional, no dia 18/06/2024, estava cond', 'Suspensão por não usar sinto de segurança.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (119, 'Suspensão por perda de agenda', 'suspensao', 'Vossa Senhoria, na condição de motorista profissional, foi devidamente comunicado e orientado quanto ao horário estabelecido para o início da viagem em 01/06/2025, estando ciente de que a balança fecharia em determinado horário e que sua reabertura ocorreria apenas às 22h. Contudo, foi identificado o descumprimento da ordem direta da gestão, o que resultou no início tardio da viagem. Tal conduta implicou na impossibilidade de pesagem do veículo, provocando atraso logístico no Terminal de Processamento e Separação da BRF (TPS BRF), perda de agenda, transtornos operacionais significativos e exposição negativa da imagem da empresa perante o cliente. Diante da gravidade da infração cometida, e com base nos princípios da subordinação e boa-fé contratual previstos no artigo 2º e artigo 3º da Consolidação das Leis do Trabalho (CLT), bem como na previsão do artigo 482 da CLT, que trata das penalidades aplicáveis em caso de ato de previsto na alienas “E e H” dissidia e indisciplina, fica aplica', 'Vossa Senhoria, na condição de motorista profissional, foi devidamente comunicado e orientado quanto', 'Suspensão por perda de agenda.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (120, 'Suspensão por recusa em viajar', 'suspensao', 'Por meio deste, comunicamos que, após apuração interna, foi constatada sua recusa injustificada em realizar viagem de transporte no veículo de placas FKZ-5896, com destino à cidade de Juiz de Fora/MG, conforme escala previamente estabelecida e comunicada em tempo hábil. Tal atitude configura insubordinação, em desacordo com o disposto no artigo 482, alínea “h”, da Consolidação das Leis do Trabalho (CLT), que prevê como justa causa para rescisão do contrato de trabalho o ato de insubordinação ou indisciplina. Ainda que a medida adotada no presente momento seja de caráter disciplinar e corretivo (suspensão), a reincidência poderá ensejar medidas mais severas, inclusive a rescisão por justa causa. Além disso, sua recusa comprometeu a operação logística da empresa, gerando atrasos e prejuízos operacionais, e impactou negativamente a imagem da Framento perante o embarcador e demais partes envolvidas no processo de transporte. Diante dos fatos, comunicamos a aplicação da penalidade de suspen', 'Por meio deste, comunicamos que, após apuração interna, foi constatada sua recusa injustificada em r', 'Suspensão por recusa em viajar.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (121, 'Suspensão por recusar em viajar', 'suspensao', 'A empresa TRANSPORTES FRAMENTO LTDA, por meio de seu representante legal, no exercício regular do poder diretivo e disciplinar que lhe confere o artigo 2º da Consolidação das Leis do Trabalho (CLT), bem como em conformidade com o dever de obediência às normas internas previsto no artigo 482, alínea “e” e “h”, da CLT,  (dissidia e insubordinação) comunica a aplicação da presente medida disciplinar. Conforme apurado, Vossa Senhoria, na condição de motorista profissional, no dia 29/08/2025, recusou-se a realizar a viagem programada com o veículo de placas ESR1I72, devidamente carregado e destinado à cidade de Juiz de Fora/MG. Tal recusa, injustificada e sem prévia comunicação à gestão responsável, ocasionou graves transtornos operacionais, incluindo o atraso no cumprimento das obrigações contratuais da empresa e, sobretudo, a exposição negativa da imagem institucional perante clientes e parceiros comerciais. Diante da gravidade da conduta, caracterizada como ato de indisciplina, a empresa', 'A empresa TRANSPORTES FRAMENTO LTDA, por meio de seu representante legal, no exercício regular do po', 'Suspensão por recusar em viajar.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (122, 'Suspensão por se deslocar com veiculo da emrepresa sem autrização', 'suspensao', 'Após apuração interna, constatamos que, no dia 11/02/2025, você utilizou o veículo da empresa, identificado pelas placas EWU7C25 / QJO7899, que estava na base em Itupeva - SP para deslocamento até sua residência em Rio das Pedras - SP, sem a devida autorização do gestor responsável. Essa conduta vai contra as normas internas da empresa, gerando custos adicionais de combustível e impactando a operação da frota Durante esse período, você deverá se abster de exercer qualquer atividade relacionada à empresa, não havendo remuneração correspondente aos dias de suspensão. Ressaltamos que a reincidência dessa ou de qualquer outra infração disciplinar poderá resultar em medidas mais severas, incluindo eventual rescisão contratual por justa causa. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os atos decorrentes da sua atitude, ci', 'Após apuração interna, constatamos que, no dia 11/02/2025, você utilizou o veículo da empresa, ident', 'Suspensão por se deslocar com veiculo da emrepresa sem autrização.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (123, 'Suspensão por se recusar ir bucar veiculo na oficiona mecanica', 'suspensao', 'Por meio deste, comunicamos que, devido à sua recusa injustificada em buscar o veículo de propriedade da empresa, placa LMP3H53, no dia 07/02/2025, em oficina localizada na cidade de Recife-PE, sua conduta gerou transtornos à operação da empresa. Diante do exposto, e considerando a gravidade da conduta, bem como as normas internas da empresa, aplicamos a penalidade de suspensão de 1 (um)dia, contados a partir de [10/02/2025, conforme disposto na legislação trabalhista e nas diretrizes internas da empresa Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplir de suspensão por 1 (um) dia sem remuneração, pela prática do disposto na alínea “E e H” do Art. 482 da CLT.', 'Por meio deste, comunicamos que, devido à sua recusa injustificada em buscar o veículo de propriedad', 'Suspensão por se recusar ir bucar veiculo na oficiona mecanica.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (124, 'Suspensão por se recusar viajar', 'suspensao', 'Em razão dos fatos ocorridos em 01/09/2025, quando Vossa Senhoria, na condição de motorista profissional, recusou-se a prosseguir viagem e deixou o veículo da empresa, carregado, na cidade de Gaspar/SC, contrariando determinação expressa de concluir o trajeto até Itupeva/SP antes do início das férias já programadas, informamos a aplicação da penalidade de suspensão disciplinar de 03 (três) dias, com início em 24/09/2025 e término em 26/09/2025, com retorno às atividades em 27/09/2025. Tal conduta caracteriza ato de dissidia e insubordinação, em afronta ao disposto no art. 482, alínea “e” e “h”, da Consolidação das Leis do Trabalho (CLT), bem como viola as normas internas da empresa e o dever de obediência às ordens legais do empregador, conforme previsto no art. 2º e 3º da CLT. Esclarecemos que esta medida visa preservar a disciplina e a regularidade operacional, servindo de advertência para que não se repitam condutas semelhantes. Salienta-se, ainda, que esta medida está sendo adotada', 'Em razão dos fatos ocorridos em 01/09/2025, quando Vossa Senhoria, na condição de motorista profissi', 'Suspensão por se recusar viajar.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (125, 'Suspesão bloquio Faixa preta', 'advertencia', 'Informamos que, após análise do desempenho e comportamento no exercício de suas atividades, foi constatado que, no dia 02 de novembro de 2024, durante a condução do veículo de placa BXD8D50, pertencente à frota da empresa e em serviço para o embarcador BRF, foram registradas diversas infrações de excessos de velocidade, chegando a picos de até 109 km/h, o que resultou em uma infração grave e gerou bloqueio na faixa preta do embarcador BRF, sendo vossa senhoria proibido de transportar/dirigir na BRF, gerando inúmeros transtorno operacionais.  De acordo com as normas internas e as regras de segurança da Framento, o excesso de velocidade é expressamente proibido. Essa ação é considerada uma violação grave das diretrizes de segurança que a empresa adota para proteger a integridade física dos colaboradores, parceiros e do ambiente de trabalho como um todo. De acordo com as normas internas e as regras de segurança vigentes no embarcador BRF, o uso de celular durante a condução é expressament', 'Informamos que, após análise do desempenho e comportamento no exercício de suas atividades, foi cons', 'Suspesão bloquio Faixa preta.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (126, 'adveretencia por usar logim de manobrista', 'advertencia', 'Considerando que Vossa Senhoria, na condição de motorista profissional, utilizou indevidamente o login de um manobrista para registro de jornada, informamos que tal prática é inaceitável e inadmissível nesta empresa. O correto registro da jornada de trabalho está diretamente ligado à devida remuneração e ao cumprimento das normas trabalhistas, sendo a conduta observada passível de sanções disciplinares. Fundamentação Jurídica A conduta em questão afronta normas trabalhistas e pode configurar fraude no controle de jornada, infringindo dispositivos legais, tais como: Artigo 58 da CLT – Define os limites da jornada de trabalho e a necessidade de correto controle de ponto. Artigo 482 da CLT, alínea “h” – Considera desídia no desempenho das funções motivo para demissão por justa causa. Diante disso, esta advertência tem como objetivo alertá-lo sobre a irregularidade da conduta, orientando-o a cumprir rigorosamente os procedimentos internos de registro de jornada Considerando também, que est', 'Considerando que Vossa Senhoria, na condição de motorista profissional, utilizou indevidamente o log', 'adveretencia por usar logim de manobrista.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (127, 'adveretncia por isubordinação e desvio de rota', 'advertencia', 'Vossa senhoria, na condição de motorista profissional, conduzindo o veículo da empresa, placa GDM6G24, no dia 28 de abril de 2025, cometeu condutas incompatíveis com as normas disciplinares da empresa, conforme descrito a seguir: Desrespeito ao superior hierárquico durante o exercício de suas funções, conduta que infringe os princípios de respeito e urbanidade exigidos no ambiente de trabalho; Desvio de rota não autorizado, uma vez que, após concluir entrega na cidade de Uberlândia/MG, V.Sa. deslocou-se até Araguari/MG sem prévia autorização da empresa, ocasionando custos adicionais e desnecessários; Resistência e dificuldade no atendimento da equipe de abastecimento, contrariando orientações operacionais e prejudicando a logística da empresa. Tais atitudes violam os deveres do empregado previstos no art. 482 da Consolidação das Leis do Trabalho (CLT), alíneas B e H, que se refere à insubordinação e ao mau procedimento  Informamos que esta é uma advertência disciplinar formal, devendo ', 'Vossa senhoria, na condição de motorista profissional, conduzindo o veículo da empresa, placa GDM6G2', 'adveretncia por isubordinação e desvio de rota.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (128, 'advertecia por não cumprir a intrajornada', 'advertencia', 'Vossa Senhoria, na condição de motorista profissional responsável pelo veículo de placa KRW4378, finalizou sua jornada no dia 10/03/2025, às 18h55, na cidade de Feira de Santana, e retomou a viagem no dia 11/03/2025, às 04h55, sem registrar o início da jornada, realizando esse registro apenas às 05h24. Dessa forma, constatou-se o não cumprimento do intervalo mínimo de 11 (onze) horas de descanso interjornada, conforme previsto na legislação vigente, além da falha no correto registro da jornada de trabalho. Essas práticas são consideradas inaceitáveis e inadmissíveis por esta empresa, pois comprometem tanto o cumprimento das normas trabalhistas quanto a segurança no exercício da função. Diante do exposto, esta advertência tem o objetivo de alertá-lo sobre a necessidade de seguir rigorosamente as diretrizes da empresa e a legislação aplicável, evitando a reincidência de tais condutas Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para', 'Vossa Senhoria, na condição de motorista profissional responsável pelo veículo de placa KRW4378, fin', 'advertecia por não cumprir a intrajornada.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (129, 'advertencia - insubordinação', 'advertencia', 'Considerando que Vossa Pessoa, na condição de motorista profissional, orientado e advertido verbalmente, continuou cometendo inúmeras transgressões ao logo do mês de julho, sendo elas: direção ininterrupta mais de 5h30min. Horas extras mais de 12 horas, dia de trabalho sem informar a refeição e infração de jornada extremamente longa mais de 12 horas e por fim, não vem marcando corretamente a jornada de espera nos dias que está aguardando no cliente.   Considerando também, este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando as transgressões cometida, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “b e h” do Art. 482 da CLT (incontinência de conduta, mau procedimento e Insubordinação)', 'Considerando que Vossa Pessoa, na condição de motorista profissional, orientado e advertido verbalme', 'advertencia - insubordinação.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (130, 'advertencia insubordinação', 'advertencia', 'Considerando que Vossa Senhoria, na condição de motorista profissional desta empresa, não vem cumprindo os procedimentos e políticas internas estabelecidas para o exercício da função, informamos que tal conduta é inaceitável e inadmissível, uma vez que compromete a segurança, a eficiência e a conformidade das operações empresariais. Esta advertência fundamenta-se no artigo 482, alínea “h” da Consolidação das Leis do Trabalho (CLT), que prevê como falta grave o não cumprimento das normas estabelecidas pelo empregador, bem como nas disposições contidas no regulamento interno da empresa. Diante dos fatos, Vossa Senhoria fica advertido formalmente e orientado a cumprir rigorosamente os procedimentos internos, sob pena de sanções disciplinares mais severas, podendo culminar em suspensão ou até mesmo rescisão contratual por justa causa, nos termos da legislação vigente. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fa', 'Considerando que Vossa Senhoria, na condição de motorista profissional desta empresa, não vem cumpri', 'advertencia insubordinação.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (131, 'advertencia por atolar o veículo', 'advertencia', 'No dia 17 de dezembro de 2024, foi constatado que, ao manobrar o veículo no pátio da empresa, sua desatenção resultou no atolamento do caminhão, o que ocasionou diversos transtornos operacionais e atrasos em nossas atividades. Essa situação demonstra falta de atenção durante a execução de uma tarefa que exige cautela e comprometimento. Lembramos que atitudes como essa podem impactar negativamente a operação da empresa e comprometer o bom andamento de nossas atividades. Desta forma, informamos que este documento constitui uma advertência formal, sendo um registro de conduta inadequada. Pedimos que, em futuras ocasiões, redobre sua atenção e observe as práticas de segurança e responsabilidade exigidas em suas funções. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os prejuízos decorrentes da sua atitude, cientificamos Vossa', 'No dia 17 de dezembro de 2024, foi constatado que, ao manobrar o veículo no pátio da empresa, sua de', 'advertencia por atolar o veículo.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (132, 'advertencia por atraso no caregamento', 'advertencia', 'Através deste documento, notificamos Vossa Senhoria de que foi constatada a ausência de comparecimento no município de Santo Inácio - PR, em 24/05/2024, conforme a programação de carregamento previamente acordada e comunicada com a devida antecedência. Tal descumprimento resultou em perda de agenda junto ao cliente, pagamento de diária do caminhão, além de prejuízos logísticos e operacionais relevantes para a empresa. Ainda, a falha comprometeu negativamente a imagem da empresa perante o cliente, afetando diretamente a confiança e a credibilidade conquistadas ao longo do relacionamento comercial. Considerando as implicações geradas, esta conduta infringe os princípios de responsabilidade, pontualidade e zelo previstos nas diretrizes internas da empresa, bem como os deveres gerais do trabalhador ou prestador de serviço. Nos termos do art. 482 da Consolidação das Leis do Trabalho (CLT), constitui falta passível de advertência o comportamento que compromete o bom andamento das atividades ', 'Através deste documento, notificamos Vossa Senhoria de que foi constatada a ausência de comparecimen', 'advertencia por atraso no caregamento.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (133, 'advertencia por carrona', 'advertencia', 'Por meio desta, a Framento Transportes vem, formalmente, suspendê-lo pelo período de 3 (três) dias, com início em 15/01/2026 e término em 17/01/2026, em razão do descumprimento das normas internas da empresa e do cliente AB BRASIL. Conforme apurado, no dia 12/01/2026, Vossa Senhoria, na condição de motorista profissional e responsável pelo veículo de propriedade da empresa, placa TUV1D20, transportou sua esposa como carona no referido veículo, bem como a utilizou como “chapa” no momento do descarregamento. Tal conduta não é aceita pela empresa, tampouco pelo embarcador AB BRASIL. Ressaltamos que essa atitude contraria as diretrizes do embarcador e as normas internas da Framento Transportes, as quais proíbem expressamente o transporte de terceiros sem autorização prévia. O descumprimento dessas regras compromete a segurança operacional e pode gerar consequências mais severas em caso de reincidência. Em decorrência de sua atitude, o embarcador proibiu temporariamente o acesso de Vossa Se', 'Por meio desta, a Framento Transportes vem, formalmente, suspendê-lo pelo período de 3 (três) dias, ', 'advertencia por carrona.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (134, 'advertencia por excesso de valocidade', 'advertencia', 'Considerando que Vossa Pessoa, na condição de motorista profissional, responsável pelo veículo (Placa ______), foi negligente no desempenho das suas funções no mês de julho/2024 por exceder os limites de velocidade, pratica está inaceitável por esta empresa.   Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os prejuízos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do disposto na alínea “ H” do Art. 482 da CLT, (indisciplina). ', 'Considerando que Vossa Pessoa, na condição de motorista profissional, responsável pelo veículo (Plac', 'advertencia por excesso de valocidade.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (135, 'advertencia por falta ao trabalho', 'advertencia', 'Por meio deste documento, informamos que foi constatada sua ausência ao trabalho no dia 17 e 18 de março 2025, sem a devida comunicação ou apresentação de justificativa válida conforme previsto nas normas internas da empresa e na legislação trabalhista aplicável. Ressaltamos que a assiduidade é um dos deveres fundamentais de todo colaborador, sendo essencial para o bom andamento das atividades da empresa e para o cumprimento de nossos objetivos coletivos. Diante do ocorrido, esta advertência tem como finalidade formalizar a irregularidade, orientar sobre a importância do cumprimento das normas e evitar a reincidência da conduta. Reforçamos que, em caso de dúvidas, você poderá procurar o setor de Recursos Humanos para esclarecimentos. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os prejuízos decorrentes da sua atitude, c', 'Por meio deste documento, informamos que foi constatada sua ausência ao trabalho no dia 17 e 18 de m', 'advertencia por falta ao trabalho.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (136, 'advertencia por iniciar a jornada antes', 'advertencia', 'Messias Jose Fidelis  Por meio desta, a empresa TRANSPORTES FRAMENTO LTDA, na pessoa de seu representante legal, vem aplicar advertência disciplinar formal em razão de conduta reiterada em descumprimento das normas internas relativas ao controle de jornada. No dia 18 de julho de 2025, foi constatado que Vossa Senhoria iniciou sua jornada de trabalho antes do horário contratualmente pactuado, prática já anteriormente observada e pela qual fora devidamente orientada e advertida verbalmente por seu gestor imediato. Destacamos que tal conduta configura descumprimento de obrigação contratual e desrespeito à jornada previamente estabelecida, sendo vedado o início antecipado das atividades sem autorização prévia da chefia. A prática compromete o controle da jornada de trabalho, viola o disposto no art. 58 da Consolidação das Leis do Trabalho (CLT), além de desrespeitar os limites legais impostos pela Lei nº 13.467/2017 (Reforma Trabalhista) e a ADI5322. Nos termos do art. 58 da CLT, a jornada', 'Messias Jose Fidelis  Por meio desta, a empresa TRANSPORTES FRAMENTO LTDA, na pessoa de seu represen', 'advertencia por iniciar a jornada antes.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (137, 'advertencia por nao prestar conta ao cliente', 'advertencia', 'Por meio deste, registramos advertência formal em razão do atraso na prestação de contas referente ao veículo de placa GAR8A48, o que resultou em transtornos junto ao cliente. Tal conduta compromete a eficiência dos processos internos e afeta a credibilidade da empresa perante seus clientes. Ressaltamos a importância do cumprimento dos prazos estabelecidos para evitar futuros inconvenientes. Solicitamos que redobre a atenção em relação a suas responsabilidades e cumpra os procedimentos internos rigorosamente. Em caso de reincidência, poderão ser aplicadas medidas disciplinares mais severas, conforme as normas da empresa Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de advertência, pela prática do dispos', 'Por meio deste, registramos advertência formal em razão do atraso na prestação de contas referente a', 'advertencia por nao prestar conta ao cliente.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (138, 'advertencia por não fazer exame toxicológico', 'advertencia', 'Conforme registrado, no mês de dezembro de 2024, você foi previamente agendado para realizar a coleta de material para exame toxicológico obrigatório, mas não compareceu no dia estipulado Diante disso, foi concedida uma nova oportunidade, com reagendamento da coleta para o dia 02 de janeiro de 2025, porém, novamente não houve seu comparecimento. Tal conduta constitui descumprimento das orientações e compromissos estabelecidos pela empresa e pode acarretar implicações legais e administrativas, considerando a importância de tais exames para a manutenção da conformidade com as normas regulamentadoras e políticas internas. Sendo assim, esta advertência tem o objetivo de formalizar a irregularidade ocorrida e orientá-lo a evitar situações semelhantes no futuro. Caso este comportamento persista, medidas disciplinares mais severas poderão ser aplicadas, conforme previsto no Regimento Interno da empresa e na legislação trabalhista aplicável. Solicitamos que compareça imediatamente ao setor de ', 'Conforme registrado, no mês de dezembro de 2024, você foi previamente agendado para realizar a colet', 'advertencia por não fazer exame toxicológico.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (139, 'advertencia por palavras de baixo calão', 'advertencia', 'Por meio desta, comunicamos-lhe que foi constatado o uso de palavras de baixo calão no grupo de trabalho do qual faz parte. Tal conduta é considerada inadequada, inaceitável e inadmissível no ambiente corporativo desta empresa, uma vez que fere os princípios de respeito, ética e profissionalismo que valorizamos. Dessa forma, esta advertência formal serve como um alerta para que tais atitudes não se repitam. O não cumprimento das normas de conduta da empresa poderá resultar em medidas disciplinares mais severas, conforme previsto no nosso regulamento interno. Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar advertência, pela prática do disposto na alínea “E e H” do Art. 482 da CLT (Dissidia e ato de indisci', 'Por meio desta, comunicamos-lhe que foi constatado o uso de palavras de baixo calão no grupo de trab', 'advertencia por palavras de baixo calão.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (140, 'advertencia por recusa em fazer toxicológico', 'advertencia', 'Vossa Senhoria, na condição de motorista profissional, foi sorteada para realizar exame toxicológico randômico no dia 03/08/2025, conforme previsto na Portaria MTE nº 612/2024, mas recusou-se, de forma imotivada, a cumprir tal determinação, mesmo ciente de que o custo do exame é integralmente custeado pela empresa, nos termos da referida norma. Ressaltamos que, segundo a Portaria MTE nº 612/2024, que altera a Portaria MTP nº 672, de 8 de novembro de 2021, o empregador poderá, a qualquer tempo, submeter motoristas profissionais a exames toxicológicos de forma randômica, com finalidade preventiva e de promoção da saúde e segurança no ambiente de trabalho. A recusa injustificada à realização de exames exigidos por normas legais e regulamentares configura descumprimento de dever funcional e ato de insubordinação, passível de aplicação de medidas disciplinares, nos termos dos arts. 482 e 158 da Consolidação das Leis do Trabalho (CLT). Diante disso, e visando corrigir a conduta para evitar r', 'Vossa Senhoria, na condição de motorista profissional, foi sorteada para realizar exame toxicológico', 'advertencia por recusa em fazer toxicológico.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (141, 'advertencia por se negars viajar', 'advertencia', 'Conforme apurado, no dia 07 janeiro de 2025, você se recusou a cumprir a ordem de viajar, sem apresentar justificativa plausível para tal decisão. Tal conduta gerou impactos negativos na operação da empresa, comprometendo o bom andamento das atividades e prejudicando o planejamento previamente estabelecido. Lembramos que é responsabilidade de todos os colaboradores cumprir as diretrizes estabelecidas pela empresa, respeitando as atribuições designadas no contrato de trabalho e as demandas necessárias para a realização das atividades. Essa advertência tem caráter disciplinar e busca reforçar a necessidade do cumprimento de suas obrigações contratuais e o compromisso com o bom funcionamento das operações da empresa Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pesso', 'Conforme apurado, no dia 07 janeiro de 2025, você se recusou a cumprir a ordem de viajar, sem aprese', 'advertencia por se negars viajar.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (142, 'advertencia retorno de viagem antecipadamente', 'advertencia', 'Vossa Senhoria, na qualidade de colaborador desta empresa, retornou do cliente durante a entrega na cidade de Fortaleza/CE, sem a devida autorização do gestor imediato, fato ocorrido em 08/07/2025. Tal conduta resultou em problemas operacionais junto ao embarcador BRF, afetando negativamente a programação logística da empresa e comprometendo a relação comercial com o referido parceiro. Esse comportamento caracteriza descumprimento de ordem direta de superior hierárquico e falha grave no cumprimento dos procedimentos operacionais internos, infringindo o disposto no artigo 482, alínea "h" da Consolidação das Leis do Trabalho (CLT), que trata da insubordinação, podendo configurar motivo para medidas disciplinares. Diante do exposto, esta advertência tem por finalidade alertá-lo formalmente quanto à irregularidade cometida e orientá-lo a não reincidir neste tipo de conduta, sob pena de aplicação de sanções mais severas, conforme previsto na legislação vigente e nas normas internas da empre', 'Vossa Senhoria, na qualidade de colaborador desta empresa, retornou do cliente durante a entrega na ', 'advertencia retorno de viagem antecipadamente.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (143, 'advertencia- por uso de celular', 'advertencia', 'Na qualidade de motorista profissional vinculado a esta empresa, informamos que, conforme apurado em relatório de ocorrência datado de 12/07/2025, foi constatado que Vossa Senhoria, ao conduzir o veículo de propriedade da Transportes Framento, conjunto de placas GIH2E24/FYH3F98, fez uso de aparelho telefônico durante o trajeto, em flagrante desacordo com as normas internas de segurança viária e em afronta à legislação vigente. Tal conduta resultou em sérios transtornos operacionais, que além de fazer o uso do celular houve também oclusão de câmera de monitoramento interna. Essa medida comprometeu diretamente o fluxo logístico da empresa e prejudicou sua imagem institucional perante o referido cliente, o que se revela absolutamente incompatível com a conduta profissional esperada de nossos colaboradores. A atitude ora descrita caracteriza ato de indisciplina e desídia no desempenho das funções, nos termos do artigo 482, alíneas “e” e “h” da Consolidação das Leis do Trabalho (CLT), confo', 'Na qualidade de motorista profissional vinculado a esta empresa, informamos que, conforme apurado em', 'advertencia- por uso de celular.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (144, 'supensão por atraso na entrega', 'advertencia', 'Por meio desta, a Framento Transportes, vem formalmente adverti-lo em razão do descumprimento das normas internas da empresa e do cliente BRF. Conforme apurado, no dia 13/02/2025, Vossa Senhoria, na condição de motorista profissional e responsável pelo veículo de propriedade da empresa, conjunto de placa EHC0H34/MJQ9075, transportou sua esposa como carona no referido veículo, que é dedicado ao embarcador BRF. Tal conduta contraria as diretrizes da BRF e as normas internas da Framento, as quais proíbem expressamente o transporte de terceiros sem autorização prévia. Ressaltamos que o descumprimento dessas regras compromete a segurança operacional, podendo gerar consequências mais severas em caso de reincidência. Em face de vossa atitude o embarcador proibiu nossa senhoria de entrar no condomínio, o qual foi necessária uma força tarefa para conseguir restabelecer vosso acesso as dependências do embarcador. Solicitamos que se atente ao cumprimento rigoroso das normas e procedimentos da emp', 'Por meio desta, a Framento Transportes, vem formalmente adverti-lo em razão do descumprimento das no', 'supensão por atraso na entrega.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (145, 'suspensao insubordinação', 'suspensao', 'Em razão dos fatos ocorridos no dia 01/10/2025, quando Vossa Senhoria, na condição de motorista profissional, recusou-se a prosseguir viagem, sendo necessário acionar um motorista diarista para dar continuidade ao trajeto, a empresa decide aplicar a penalidade de suspensão disciplinar de 03 (três) dias, com início em 01/10/2025 e término em 03/10/2025, devendo retomar suas atividades normais em 04/10/2025. Tal conduta caracteriza ato de desídia e insubordinação, em desacordo com o disposto no artigo 482, alíneas “e” e “h” da Consolidação das Leis do Trabalho (CLT), além de violar normas internas da empresa e o dever de obediência às ordens legais do empregador, conforme os artigos 2º e 3º da CLT. Esclarecemos que esta medida visa preservar a disciplina interna e a regularidade das operações, servindo como advertência para que atitudes semelhantes não se repitam. Ressaltamos ainda que a presente penalidade está sendo aplicada em conformidade com o princípio da imediatidade, atendendo ao', 'Em razão dos fatos ocorridos no dia 01/10/2025, quando Vossa Senhoria, na condição de motorista prof', 'suspensao insubordinação.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (146, 'suspenssão por excesso de velocidade', 'advertencia', 'Conforme apurado em nossos registros internos, foi constatado que, no dia 03/03/2025, vossa senhoria excedeu diversas vezes os limites de velocidade permitidos por lei e pela política interna da Framento Transportes, atingindo a velocidade de 85 km/h, quando o limite máximo permitido é de 80 km/h. Considerando que o ato de ultrapassar o limite de velocidade estabelecido não apenas infringe as normas de trânsito, mas também coloca em risco a sua segurança, de outros motoristas e a integridade do patrimônio da empresa.  Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considerando os riscos decorrentes da sua atitude, cientificamos Vossa Pessoa de que a empresa está aplicando penalidade disciplinar de suspensão sem remuneração e DSR, por 3 (três) dias, pela prática do disposto na alínea “E e H” do Art. 482 da CLT. ', 'Conforme apurado em nossos registros internos, foi constatado que, no dia 03/03/2025, vossa senhoria', 'suspenssão por excesso de velocidade.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (147, 'suspenssão por uso de cular e carrona', 'advertencia', 'Por meio desta, a empresa Transportes Framento na qualidade de sua empregadora, vem, com fundamento no artigo 482 da Consolidação das Leis do Trabalho (CLT), aplicar-lhe a penalidade de suspensão disciplinar, pelos fatos e fundamentos a seguir expostos: No exercício de suas atividades profissionais no dia 24/04/2025, enquanto conduzia veículo de propriedade da empresa placa SRS4E93, o senhor foi flagrado: Utilizando aparelho celular durante a direção, infringindo normas internas da empresa, diretrizes de segurança do trabalho, bem como disposições do Código de Trânsito Brasileiro (Lei 9.503/97), notadamente o artigo 252, inciso VI, que veda o uso de telefone celular enquanto dirige veículo; e Transportando acompanhante não autorizado na cabine do caminhão, contrariando expressa orientação de segurança da empresa e as normas de embarque da contratante BRF. Tais condutas culminaram no bloqueio de seu acesso às unidades da empresa BRF até 09/05/2025, conforme comunicação formal daquela em', 'Por meio desta, a empresa Transportes Framento na qualidade de sua empregadora, vem, com fundamento ', 'suspenssão por uso de cular e carrona.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (148, 'suspensão deslocamento do veiculo sem autorização', 'suspensao', 'Considerando que, no dia 20 de março de 2025, Vossa Senhoria deslocou-se sem autorização da cidade de Londrina-PR para Itapecerica da Serra-SP, percorrendo aproximadamente 540 km, sem comunicação prévia e realizando o deslocamento durante o período noturno, além de ter permanecido incomunicável no dia seguinte, descumprindo ordens diretas da empresa, comunicamos a aplicação de suspensão disciplinar pelos seguintes motivos: Descumprimento de ordem direta, conforme previsto no art. 482, alínea "h" da Consolidação das Leis do Trabalho (CLT), que trata da insubordinação e indisciplina do empregado; Prejuízo financeiro causado à empresa no valor de R$ 1.710,00 referente a custos de óleo diesel e pedágios; Exposição negativa da imagem da empresa, comprometendo sua reputação e operação Considerando também, que este é o primeiro contato com Vossa Pessoa, após as diligências necessárias para apuramento dos fatos por esta empresa, com observância ao princípio da imediatidade da medida. Considera', 'Considerando que, no dia 20 de março de 2025, Vossa Senhoria deslocou-se sem autorização da cidade d', 'suspensão deslocamento do veiculo sem autorização.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (149, 'suspensão por atraso na entrega sem justificativa', 'suspensao', 'Considerando os fatos ocorridos nos dias 17 e 18 de fevereiro de 2025, onde Vossa Senhoria, na condição de motorista profissional e responsável pelo veículo de placa EGT4E81, atrasou a entrega da mercadoria destinada ao cliente BRF, alegando furo no pneu do caminhão durante a viagem, sem que houvesse comunicação imediata à empresa sobre o ocorrido e sem registro de manutenção para o referido reparo, conforme verificamos em nossos controles internos, informamos que: O atraso resultou na chegada ao destino apenas no dia 18/02, contrariando a programação original para o dia 17/02; O cliente BRF, apesar de ter recebido a mercadoria, recusou o recebimento da mesma, e aplicou uma penalidade financeira por improdutividade, ocasionando um prejuízo de R$ 2392,44 à empresa Framento, além dos custos adicionais de combustível e transtornos operacionais; O conserto de um pneu furado é um procedimento que, em condições normais, leva no máximo uma hora, não justificando o atraso excessivo na entrega;', 'Considerando os fatos ocorridos nos dias 17 e 18 de fevereiro de 2025, onde Vossa Senhoria, na condi', 'suspensão por atraso na entrega sem justificativa.docx', true);
INSERT INTO warning_templates (categoryId, title, type, content, summary, sourceFile, isActive) VALUES (150, 'suspensão por excesso de velocidade ', 'suspensao', 'Após análise dos registros do sistema de monitoramento e controle de velocidade da frota da empresa Transportes Framento, constatou-se que, no dia 27/08/2025, Vossa Senhoria, durante a condução do veículo de placa TUX0JPP, excedeu várias vezes os limites de velocidade permitido, atingindo a marca de 91 km/h, em condições de pista seca, quando a política interna da empresa estabelece a velocidade máxima de 80 km/h. Tal conduta, além de configurar descumprimento das normas internas de segurança, representou grave risco à integridade física do condutor, de terceiros, à segurança viária e ao patrimônio da empresa, agravado pelo fato de ter ocorrido em condições climáticas adversas (chuvas), aumentando significativamente o potencial de acidentes. Nos termos do artigo 2º da Consolidação das Leis do Trabalho (CLT), compete ao empregador dirigir a prestação pessoal de serviços e adotar medidas disciplinares necessárias à preservação da ordem, segurança e eficiência no ambiente laboral. A prese', 'Após análise dos registros do sistema de monitoramento e controle de velocidade da frota da empresa ', 'suspensão por excesso de velocidade .docx', true);